// Üretilen dosya: tool/ozgun/uret.py. Doğa · Memeliler ayrıntılı (orta).
const ozNature6Orta = <(String, String, List<String>, String)>[
  ('Memelilerin alt çenesini diğer omurgalılardan ayıran özellik hangisidir?', 'Her yarısının tek bir kemikten (dentari) oluşması', ['Ön ucunda dişsiz bir boynuz gaga bulunması', 'Kafatasına yalnızca kıkırdakla bağlanması', 'Dört ayrı kemiğin kaynaşmasıyla oluşması'], 'Memelilerde alt çenenin her yarısı yalnızca dentari kemiğinden oluşur; sürüngen atalardaki diğer çene kemikleri orta kulak kemikçiklerine dönüşmüştür.'),
  ('Memelilerin büyük çoğunluğunda olgun alyuvarlar hakkında hangisi doğrudur?', 'Çekirdeksizdir', ['İki çekirdeklidir', 'Oval ve çekirdeklidir', 'Hemoglobin taşımaz'], 'Memelilerin olgun alyuvarları gelişim sırasında çekirdeğini kaybeder; böylece hücrede hemoglobin için daha fazla yer kalır. Kuş, sürüngen ve balıkların alyuvarları çekirdeklidir.'),
  ('Kemik yapısı incelenen bir fosilin ağız tavanında, burun boşluğunu ağızdan tamamen ayıran kemik bir damak bulunuyor. Bu yapının memelilere sağladığı başlıca yarar nedir?', 'Çiğnerken ve emerken soluk alabilmek', ['Koku alma yüzeyini iki katına çıkarmak', 'Çene kaslarının kütlesini küçültmek', 'Su altında daha uzun süre kalabilmek'], 'İkincil damak, hava yolunu ağızdan ayırır; böylece yavru emerken, erişkin de uzun süre çiğnerken solunum kesintiye uğramaz.'),
  ('İlk gerçek memeliler yaklaşık hangi jeolojik dönemde ortaya çıkmıştır?', 'Triyas sonu ile Jura başı', ['Kambriyen başlangıcı', 'Kretase dönemi sonu', 'Neojen dönemi ortası'], 'Morganucodon gibi ilk memeli biçimleri yaklaşık 200 milyon yıl önce, Triyas\'ın sonu ile Jura\'nın başı arasında, dinozorlarla aynı dönemde ortaya çıkmıştır.'),
  ('Dinozorlar çağında yaşamış memelilerin büyük çoğunluğu küçük yapılı ve gececiydi. Bu durumun en akla yatkın açıklaması hangisidir?', 'Gündüz etkin büyük sürüngenlerle rekabetten ve avlanmaktan kaçınmak', ['Ağaçlarda yetişen meyvelerin yalnızca geceleri olgunlaşması ve toplanabilmesi', 'O dönemde güneş ışığının çok zayıf olması', 'Memelilerin gözlerinin henüz gelişmemiş olması'], 'Mezozoyik memelileri büyük ölçüde küçük ve gece etkin kalmıştır; bu durum, gündüzü egemenlik altına almış dinozorlarla rekabet ve avlanma baskısıyla açıklanır.'),
  ('Yaklaşık 66 milyon yıl önceki kitlesel yok oluştan sonra memelilerin hızla çeşitlenip büyük boyutlara ulaşmasının temel nedeni nedir?', 'Dinozorların boşalttığı ekolojik nişlerin doldurulması', ['Atmosferdeki oksijenin aniden ikiye katlanması', 'Memelilerin o dönemde ilk kez ortaya çıkması', 'Bütün kıtaların yeniden tek bir büyük kıtada birleşerek göçü kolaylaştırması'], 'Kuşlar dışındaki dinozorların ortadan kalkmasıyla açılan nişler, uyarlanımsal açılım sürecinde memeliler tarafından hızla dolduruldu.'),
  ('Memelilerin sürüngen benzeri atalarında yayvan duran bacakların zamanla gövdenin altına yerleşmesi hangi sonucu doğurmuştur?', 'Daha verimli koşu ve hareket sırasında rahat soluk alma', ['Yüzme ve tırmanma yeteneğinin tümüyle ortadan kalkması', 'Kuyruğun bütün soylarda tamamen kaybolması', 'Vücut ısısının çevreye bağımlı hâle gelmesi'], 'Bacakların gövde altına alınması, yürürken gövdenin yanlara kıvrılmasını azaltır; bu da hızlı koşuyu ve aynı anda soluk almayı kolaylaştırır.'),
  ('Ornitorenk ve ekidnelerin dahil olduğu monotremlerin adı neyi anlatır?', 'Boşaltım, sindirim ve üreme için tek bir açıklığın bulunmasını', ['Her üreme döneminde tek bir yavru dünyaya getirmelerini', 'Yalnızca tek bir meme bezlerinin bulunmasını', 'Tek renk görebilmelerini'], 'Monotrem \'tek delikli\' anlamına gelir; bu hayvanlarda kuş ve sürüngenlerdeki gibi bir kloak bulunur.'),
  ('Kısa gagalı ekidne yumurtasını nerede kuluçkaya yatırır?', 'Karnında geçici olarak oluşan bir kesede', ['Toprağa kazdığı derin ve nemli bir çukurda', 'Ağaç kovuklarında kurduğu yaprak yuvalarda', 'Sırtındaki dikenlerin arasında'], 'Dişi ekidne tek yumurtasını karnındaki geçici keseye koyar; yavru (puggle) yumurtadan bu kesede çıkar ve dikenleri gelişene kadar orada kalır.'),
  ('Keseli memelilerde yavrunun anne karnında kısa süre kaldıktan sonra çok erken doğmasının nedeni nedir?', 'Plasentalarının kısa süreli ve basit olması', ['Annenin rahminde yavruya yetecek alan bulunmaması', 'Yavrunun doğar doğmaz kendi besinini bulabilmesi', 'Embriyonun yalnızca yumurta sarısıyla beslenmesi'], 'Keselilerin çoğunda yalnızca kısa ömürlü, basit bir plasenta oluşur; bu nedenle yavru az gelişmiş doğar ve gelişimini meme üzerinde sürdürür.'),
  ('Vombatların yuvalarına giren bir avcıya karşı kullandığı savunma hangisidir?', 'Kıkırdaklı sert sağrısıyla tüneli tıkamak', ['Kuyruğundaki zehirli dikenleri fırlatmak', 'Anal bezlerinden kötü kokulu sıvı püskürtmek', 'En yakın ağaca tırmanıp yapraklara saklanmak'], 'Vombatın arka kısmında kalın deri, kıkırdak ve kemikten oluşan sert bir kalkan bulunur; tünele giren avcıya bu kalkanla yolu kapatır.'),
  ('Tazmanya canavarının beslenme biçimi en iyi hangi seçenekte tanımlanır?', 'Avlanmanın yanı sıra büyük ölçüde leşle beslenen etçil', ['Yalnızca okaliptüs yaprağı yiyen otçul', 'Nektar ve polenle beslenen bir tozlaştırıcı', 'Yalnızca termit yiyen böcekçil'], 'Tazmanya canavarı bugün yaşayan en büyük etçil keselidir; çok güçlü çenesiyle kemikleri bile kırarak leşleri tüketir.'),
  ('Avustralya\'da yaşayan numbat (bantlı karıncayiyen) ile Güney Amerika\'daki karıncayiyenler benzer beslenir ama akraba değildir. Numbat hangi gruptadır?', 'Keseliler', ['Tembel hayvanlar ve armadillolarla aynı grupta', 'Kemirgenler', 'Böcekçiller'], 'Numbat termitle beslenen keseli bir memelidir; karıncayiyenlerle benzerliği yakınsak evrimin örneğidir.'),
  ('Avustralya\'nın yerli memeli faunasında plasentalılar dışında keselilerin bu denli egemen olmasının en önemli nedeni hangisidir?', 'Kıtanın uzun süre diğer kıtalardan yalıtılmış kalması', ['Avustralya ikliminin plasentalıları kısırlaştırması', 'Keselilerin bütün plasentalılardan daha zeki olması', 'Plasentalıların Avustralya\'ya hiç ulaşamamış olması'], 'Avustralya, Gondvana\'dan ayrıldıktan sonra uzun süre yalıtılmış kaldı ve keseliler burada çeşitlendi. Yine de yarasalar ve kemirgenler gibi plasentalılar da kıtaya ulaşmıştır.'),
  ('Görünüşü kobaya benzeyen, kayalık alanlarda yaşayan damanların (hyrax) yaşayan en yakın akrabaları arasında hangileri sayılır?', 'Filler ve deniz inekleri', ['Tavşanlar ve pikalar', 'Kemirgenler ve sincaplar', 'Kirpiler ve sivri fareler'], 'Damanlar, görünüşlerine rağmen Afrika kökenli Afrotheria grubundadır ve fillerle deniz ineklerinin akrabasıdır.'),
  ('Kayalık damanlarının ayak tabanlarındaki nemli, lastik gibi yastıklar onlara hangi yeteneği kazandırır?', 'Dik kaya yüzeylerine tutunarak tırmanma', ['Suyun üstünde koşabilme', 'Kumu hızla kazabilme', 'Kar üstünde batmadan yürüme'], 'Daman tabanlarındaki bezler yastıkları nemli tutar ve kas yapısı vantuz etkisi yaratır; bu sayede dik kayalara rahatça tırmanırlar.'),
  ('Yer domuzunun (aardvark) kazdığı büyük yuvalar savanda başka canlılar için neden önemlidir?', 'Terk edilen yuvalar pek çok hayvana barınak olur', ['Yağmur suyunu toprağa ulaştırmayı tamamen engeller', 'Termitlerin sayısını sıfıra indirir', 'Otların köklerini kurutarak çölleşmeyi hızlandırır'], 'Yer domuzunun bıraktığı yuvaları sırtlan, yaban domuzu, kirpi ve birçok kuş türü barınak olarak kullanır.'),
  ('Madagaskar\'da yaşayan tenreklerin bir bölümü kirpiye, bir bölümü sivri fareye, bir bölümü su samuruna benzer. Bu çeşitlenme hangi süreçle açıklanır?', 'Uyarlanımsal açılım', ['Yapay seçilim', 'Genetik sürüklenmeyle türlerin birleşmesi', 'Melezleşme yoluyla tür kaybı'], 'Madagaskar\'a ulaşan tek bir ata soy, adadaki boş nişleri doldurarak farklı biçimlere ayrışmıştır; buna uyarlanımsal açılım denir.'),
  ('Tembel hayvanların ağaç dallarında baş aşağı asılı kalırken çok az enerji harcamasını sağlayan özellik hangisidir?', 'Kıvrık uzun pençelerinin kas gücü gerektirmeden dala kilitlenmesi', ['Kuyruklarıyla dala sarılmaları', 'Ayak tabanlarındaki yapışkan bezler', 'Dala bağlanan ipeksi salgılar'], 'Tembel hayvanların çengel gibi pençeleri dal üzerinde kendiliğinden kapanık kalır; bu sayede uyurken bile düşmeden asılı durabilirler.'),
  ('Dev karıncayiyen bir termit yuvasında genellikle yalnız kısa süre beslenip başka yuvaya geçer. Bunun en olası nedeni nedir?', 'Askerlerin savunmasından kaçınmak ve yuvanın tükenmesini önlemek', ['Dilinin bir dakikadan uzun çalışamaması', 'Termitleri bir anda tümüyle yiyip bitirmesi', 'Yuvaların gün içinde yer değiştirmesi'], 'Kısa süreli beslenme, sokan ve ısıran asker böceklerden kaçınmayı sağlar; yuva da yok edilmediği için daha sonra yeniden kullanılabilir.'),
  ('Tembel hayvanlar, karıncayiyenler ve armadilloların birlikte oluşturduğu ve özellikle Güney Amerika\'da çeşitlenmiş memeli grubu hangisidir?', 'Xenarthra (Zayıf dişliler)', ['Afrotheria (Afrika memelileri)', 'Tubulidentata', 'Pholidota'], 'Xenarthra grubu omurlarındaki ek eklemlerle tanınır ve Güney Amerika\'nın uzun süreli yalıtımı sırasında çeşitlenmiştir.'),
  ('Üç parmaklı tembel hayvanların metabolizması hakkında hangisi doğrudur?', 'Vücut ısıları dalgalanır ve bazal metabolizmaları çok düşüktür', ['Kuşlardan daha yüksek metabolizmaya sahiptirler', 'Vücut ısıları sürekli 40 °C üzerindedir', 'Her gün vücut ağırlığı kadar yaprak yerler'], 'Tembel hayvanların metabolizması aynı boyuttaki memelilerden çok düşüktür ve vücut ısıları ortama göre birkaç derece değişebilir; güneşlenerek ısınırlar.'),
  ('Fil hortumunun ucunda parmak gibi çıkıntılar bulunur. Bu çıkıntıların sayısı iki tür arasında nasıl değişir?', 'Afrika filinde iki, Asya filinde bir tanedir', ['Afrika filinde bir, Asya filinde ise iki tanedir', 'İki türde de üçer tane bulunur', 'Yalnızca yetişkin erkeklerin hortumunda bulunur'], 'Afrika fillerinin hortum ucunda üstte ve altta iki parmaksı çıkıntı, Asya fillerinde ise yalnız üstte bir çıkıntı vardır.'),
  ('Asya fillerinde fildişi hakkında hangisi doğrudur?', 'Dişilerin çoğunda yok ya da çok küçüktür', ['Yalnızca dişilerde bulunur, erkeklerde hiç gelişmez', 'Her iki eşeyde de Afrika filininkinden daha uzun ve kalındır', 'Her yıl dökülüp kış sonunda yeniden çıkar ve büyür'], 'Asya fillerinde büyük fildişi genellikle erkeklerde görülür; dişilerde çoğunlukla \'tush\' denen küçük dişler bulunur ya da hiç yoktur.'),
  ('Çok yaşlı bir filin yeterince yiyecek bulunan bir bölgede bile zayıflayıp ölmesinin yaygın bir nedeni nedir?', 'Son azı dişlerinin de aşınıp bitmesi', ['Hortum kaslarının yaşla birlikte tamamen felç olması', 'Kulaklarının ısıyı hiç atamaz hâle gelip aşırı ısınması', 'Sürüden kovulup su kaynaklarına ulaşamayarak susuz kalması'], 'Fillerin altıncı ve son azı dişi takımı aşındıktan sonra yenisi gelmez; yaşlı filler bu nedenle besini çiğneyemeyip zayıflayabilir.'),
  ('Fillerin ayak tabanlarının yere yayılan titreşimleri algılayabildiği gösterilmiştir. Bu yetenek onlara ne sağlar?', 'Uzaktaki fillerin sesleriyle oluşan yer titreşimlerini sezmek', ['Yer altındaki su kaynaklarının sıcaklığını ölçmek', 'Toprağı kazmadan bitki köklerinin yerini tam olarak belirlemek', 'Ayak tabanlarından ter atarak vücudu soğutmak'], 'Fillerin düşük frekanslı sesleri yerde titreşim olarak da yayılır; ayak ve hortum ucundaki duyarlı reseptörler bu titreşimleri algılayabilir.'),
  ('Moleküler çalışmalarla savan filinden ayrı bir tür olarak kabul edilen, daha küçük yapılı ve daha düz, aşağı bakan fildişleri olan fil hangisidir?', 'Afrika orman fili', ['Asya fili', 'Sri Lanka fili', 'Borneo\'nun cüce fili'], 'Orta ve Batı Afrika yağmur ormanlarında yaşayan Afrika orman fili, savan filinden daha küçüktür; kulakları daha yuvarlak, fildişleri daha düz ve aşağı yönelimlidir.'),
  ('Zürafanın kalbi çok yüksek bir kan basıncı üretir. Bacaklarında kanın göllenmesini ve damar dışına sızmasını önleyen özellik nedir?', 'Bacaklardaki çok sıkı ve kalın deri', ['Bacaklarda hiç kılcal damar bulunmaması', 'Bacak kemiklerinin içinin boş olması', 'Bacaklarda sürekli titreme olması'], 'Zürafa bacaklarındaki sıkı deri ve bağ dokusu, pilot giysisi gibi dış basınç uygular; böylece yüksek basınçta sıvının dokulara sızması önlenir.'),
  ('Zürafaların başındaki boynuz benzeri çıkıntılara ne ad verilir ve bunlar hangi özelliktedir?', 'Ossikon; deri kaplı kemiklerdir', ['Kadife boynuz; her yıl dökülen kemiklerdir', 'Keratin kılıf; içi boş gerçek boynuzlardır', 'Fildişi çıkıntı; uzamış ön dişlerdir'], 'Ossikonlar zürafa ve okapide bulunan, deri ve kılla örtülü kemik çıkıntılardır; geyik boynuzu gibi dökülmez, sığır boynuzu gibi keratin kılıflı da değildir.'),
  ('Dişi zürafa doğumu ayakta yapar ve yavru yaklaşık iki metreden yere düşer. Bu düşüşün yavru için olağan işlevi nedir?', 'Göbek bağını koparmak ve soluk almayı uyarmak', ['Yavrunun kemiklerini çarpmayla sertleştirmek', 'Gürültüyle avcıları ürkütüp uzaklaştırmak', 'Annenin meme bezlerinde süt üretimini başlatmak'], 'Düşüş göbek bağını koparır ve yavrunun ilk solukları almasını uyarır; yeni doğan zürafa genellikle bir saat içinde ayağa kalkar.'),
  ('Tek hörgüçlü deve ile iki hörgüçlü (Baktriya) devesinin doğal yayılış alanları karşılaştırıldığında hangisi doğrudur?', 'Tek hörgüçlü sıcak çöllerde, iki hörgüçlü soğuk Orta Asya\'da yaşar', ['İkisi de yalnızca Sahra Çölü\'nün sıcak kumullarında yaşar', 'Tek hörgüçlü Moğolistan\'a, iki hörgüçlü Arabistan\'a özgüdür', 'İkisi de Güney Amerika kökenlidir ve yalnızca And Dağları\'nda yaşar'], 'Tek hörgüçlü deve Arabistan ve Kuzey Afrika gibi sıcak çöllerde, iki hörgüçlü deve ise kışı sert geçen Gobi gibi Orta Asya bölgelerinde yaşar.'),
  ('Fosil kayıtlarına göre devegiller ilk olarak hangi kıtada ortaya çıkıp çeşitlenmiştir?', 'Kuzey Amerika', ['Afrika', 'Avustralya', 'Güneydoğu Asya'], 'Devegillerin atası Kuzey Amerika\'da evrimleşmiş, sonra bir kolu Asya\'ya, bir kolu Güney Amerika\'ya yayılmıştır; Kuzey Amerika\'daki temsilcileri buzul çağı sonunda yok olmuştur.'),
  ('Lamanın ve alpakanın yabani ataları olarak kabul edilen Güney Amerika devegilleri hangileridir?', 'Lama için guanako, alpaka için vikunya', ['Lama için vikunya, alpaka için Baktriya devesi', 'İkisi için de tek hörgüçlü deve', 'Lama için tapir, alpaka için guanako'], 'Genetik çalışmalar lamanın guanakodan, alpakanın ise ince yünlü vikunyadan evcilleştirildiğini gösterir.'),
  ('Deve güreşlerinde kullanılan Tülü develeri nasıl elde edilir?', 'Tek hörgüçlü ve iki hörgüçlü develerin melezlenmesiyle', ['Yalnızca yabani Baktriya develerinin yakalanıp eğitilmesiyle', 'Lama ile devenin yapay yolla çiftleştirilmesiyle', 'Arap develerinin kendi içinde seçilmesiyle'], 'Tülü develeri tek ve iki hörgüçlü develerin melezidir; iri yapıları ve güçleri nedeniyle Ege\'deki deve güreşi geleneğinde tercih edilir.'),
  ('Atın en eski bilinen atalarından Eohippus (Hyracotherium) ile bugünkü at karşılaştırıldığında hangisi doğrudur?', 'Köpek boyundaydı ve çok parmaklıydı', ['Eohippus bugünkü attan iki kat büyüktü', 'Eohippus\'un ayaklarında yalnız bir toynak vardı', 'Eohippus açık otlaklarda yaşayan bir otlayıcıydı'], 'Yaklaşık 55 milyon yıl önce yaşayan Eohippus küçük bir orman hayvanıydı; ön ayaklarında dört, arka ayaklarında üç parmak bulunuyordu.'),
  ('At soyunun evriminde iklimin kurumasıyla ormanların yerini otlakların almasına eşlik eden diş değişimi hangisidir?', 'Taçları yüksek, aşınmaya dayanıklı azı dişleri', ['Köpek dişlerinin çok uzayıp kıvrılması', 'Kesici dişlerin tamamen kaybolup yerine boynuz gaga gelmesi', 'Dişlerin sivri ve koni biçimli olup sürekli yenilenmesi'], 'Otlar silika içerir ve dişleri hızla aşındırır; bu nedenle otlayan atların soyunda taçları yüksek, uzun süre aşınabilen dişler seçilmiştir.'),
  ('Atların ayakta uyuyabilmesini sağlayan mekanizma nedir?', 'Eklemleri kas gücü olmadan kilitleyen bağ düzeni', ['Uyurken kalp atışının ve solunumun tamamen durması', 'Ayak tabanlarındaki vantuz benzeri yapılar', 'Kuyruğun yere dayanarak destek olması'], 'Atlarda bacak eklemlerini kilitleyen bir tendon-bağ düzeni bulunur; bu sayede kaslar gevşese de at ayakta hafif uykuya dalabilir. Derin uyku için ise genellikle yatar.'),
  ('Bir atın sindirim sorunlarına (kolik) karşı özellikle hassas olmasının nedenlerinden biri hangisidir?', 'Atlar normal koşullarda kusamaz', ['Atların midesi geviş getirenler gibi dört bölmelidir', 'Atlar selüloz sindiremez', 'Atların bağırsağı çok kısadır'], 'Atların mide girişindeki güçlü kas halkası kusmayı neredeyse olanaksız kılar; bu nedenle midede biriken gaz veya besin ciddi sorunlara yol açabilir.'),
  ('Erkek at ile dişi eşeğin çiftleşmesinden doğan melez hayvana ne ad verilir?', 'Bardo', ['Katır', 'Kulan', 'Tarpan'], 'Katır erkek eşek ile dişi attan, bardo ise erkek at ile dişi eşekten doğar. İkisi de çoğunlukla kısırdır.'),
  ('Beyaz gergedan ile siyah gergedanın dudak biçimleri neden farklıdır?', 'Beyaz gergedan ot otlar, siyah gergedan çalı yaprağı koparır', ['Beyaz gergedan balık avlar, siyah gergedan ot yer', 'İkisi de leşle beslenir, dudaklar yalnız süstür', 'Siyah gergedan yerden ot otlar, beyaz gergedan ağaç kabuğu yer'], 'Beyaz gergedanın geniş ve düz dudağı yerden ot otlamaya, siyah gergedanın sivri ve kavrayıcı üst dudağı ise çalılardan yaprak ve dal koparmaya uygundur.'),
  ('Deri kıvrımları zırh plakalarını andıran ve tek boynuzlu olan gergedan türü hangisidir?', 'Hint gergedanı', ['Siyah gergedan', 'Sumatra gergedanı', 'Beyaz gergedan'], 'Büyük tek boynuzlu gergedan da denen Hint gergedanının derisi kalın kıvrımlar yapar; Afrika gergedanları ve Sumatra gergedanı ise iki boynuzludur.'),
  ('Görünüşleri domuza benzeyen tapirler biyolojik olarak hangi hayvanlarla aynı takımdadır?', 'Atlar ve gergedanlarla', ['Domuzlar ve su aygırlarıyla', 'Fillerle ve deniz inekleriyle', 'Kemirgenlerle'], 'Tapirler tek toynaklılar takımındadır; ağırlığı tek sayıda parmak taşır ve en yakın akrabaları at ile gergedanlardır.'),
  ('Tapir yavrularının vücudundaki açık renkli çizgi ve benekler yetişkinlerde kaybolur. Bu desenin yavrulara yararı nedir?', 'Orman tabanındaki ışık-gölge içinde gizlenmek', ['Annelerine uzaktan görünür olup sürüde kaybolmamak', 'Güneş ışığını yansıtarak serinlemek', 'Avcılara zehirli olduklarını göstermek'], 'Benekli ve çizgili desen, ormanın ışık lekeleri arasında yavruyu gizler; benzer bir desen yaban domuzu ve geyik yavrularında da görülür.'),
  ('Malezya ve Sumatra\'da yaşayan Malaya tapirinin en belirgin görünüş özelliği hangisidir?', 'Siyah gövdenin ortasında beyaz bir eyer lekesi', ['Boynun üstünde kırmızı kıllı, uzun ve dik bir yele', 'Alnında keratin kılıflı tek ve kısa bir boynuz', 'Zebra gibi siyah-beyaz çizgili bacaklar ve kuyruk'], 'Malaya tapirinin siyah vücudunun orta kısmı beyazdır; bu desen gece ve gölgede vücut hatlarını bozarak kamuflaj sağlar.'),
  ('Su aygırları her gece karada otlayıp gündüz suya döndüğünde dışkı yoluyla göl ve nehre ne taşımış olur?', 'Karadaki bitkilerden gelen besin maddelerini', ['Kıyıdaki kayalardan kopan tuz kristallerini', 'Kum ve çakılı taşıyarak göl tabanını yükseltmeyi', 'Zehirli ağır metalleri ve tarım ilaçlarını'], 'Su aygırları karada yedikleri otların besinlerini suya taşır; bu besinler sudaki balık ve omurgasızlar için önemli bir kaynak olur.'),
  ('Endonezya\'nın Sulawesi Adası\'nda yaşayan babirusa adlı domuzgilin erkeklerinde dikkat çeken özellik hangisidir?', 'Üst köpek dişlerinin burun derisini delip çıkması', ['Alnında tek bir boynuz bulunması', 'Sırtında deve gibi yağ depolayan bir hörgüç olması', 'Kuyruğunun yassı ve pullu olması'], 'Erkek babirusanın üst köpek dişleri ağız içinden değil, burnun derisini delerek yukarı ve geriye doğru büyür.'),
  ('Amerika kıtasında yaşayan pekariler ile Avrasya\'daki yaban domuzu arasındaki ilişki için hangisi doğrudur?', 'Ayrı familyalarda yer alırlar', ['Aynı türün iki farklı alt türüdürler', 'Pekariler keseli memelidir', 'Pekariler tek toynaklılardandır'], 'Pekariler domuzlara benzer ancak ayrı bir familyada (Tayassuidae) sınıflandırılır; ikisi de çift toynaklıdır.'),
  ('Bir sığırın boynuzu enine kesildiğinde nasıl bir yapı görülür?', 'Kemik bir öz ve onu saran keratin kılıf', ['Baştan sona katı ve tek parça keratin', 'İçi tamamen boş, ince kemik bir tüp', 'Üst üste binmiş kıkırdak ve deri katmanları'], 'Sığırgillerin boynuzu kafatasından çıkan kemik bir özün çevresini saran keratin kılıftan oluşur; dökülmez ve hayvan yaşadıkça büyür.'),
  ('Bugünkü evcil sığırların yabani atası kabul edilen ve son bireyi 1627\'de Polonya\'da ölen tür hangisidir?', 'Yaban sığırı (aurochs)', ['Avrupa bizonu (wisent)', 'Asya su mandası', 'Yabani yak'], 'Evcil sığır Bereketli Hilal\'de yaban sığırından (Bos primigenius) evcilleştirilmiştir; bu yabani türün son bireyi 1627\'de Polonya\'daki bir ormanda ölmüştür.'),
  ('Hindistan\'da yaygın olan, omzunda belirgin bir hörgüç ve boynunun altında sarkık deri bulunan sıcağa dayanıklı evcil sığır tipi hangisidir?', 'Zebu', ['Yak', 'Bizon', 'Gaur'], 'Zebu, Hint alt kıtasında yaban sığırının ayrı bir kolundan evcilleştirilmiştir; hörgücü ve geniş deri yüzeyi sıcak iklime uyum sağlar.'),
  ('Anadolu\'nun sarp dağlarında da yaşayan ve kendisinden evcil keçinin türediği kabul edilen hayvan hangisidir?', 'Yaban keçisi (Capra aegagrus)', ['Çengel boynuzlu dağ keçisi', 'Alp dağ keçisi (ibeks)', 'Ankara (tiftik) keçisi'], 'Evcil keçi, Zagros ve Toroslar dahil Güneybatı Asya dağlarında yaşayan yaban keçisinden yaklaşık 10.000 yıl önce evcilleştirilmiştir.'),
  ('Afrika mandası ile Asya\'nın su mandası arasındaki ilişki için hangisi doğrudur?', 'Yalnızca su mandası evcilleştirilmiştir', ['İkisi de aynı türün iki coğrafi ırkıdır', 'Afrika mandası evcil, su mandası yabanidir', 'İkisi de tek toynaklılar takımındadır'], 'Asya kökenli su mandası binlerce yıldır tarım hayvanıdır; Afrika mandası ise ayrı bir cinstir ve hiçbir zaman evcilleştirilmemiştir.'),
  ('Geyik boynuzlarının dökülme zamanını belirleyen başlıca etken nedir?', 'Kan testosteron düzeyinin düşmesi', ['Hayvanın kışın kilo kaybetmesi', 'Kalın kış kürkünün çıkmaya başlaması', 'Gün içinde hava sıcaklığının artması'], 'Çiftleşme döneminden sonra testosteron düzeyi düşünce boynuz ile kafatası arasındaki bağlantı zayıflar ve boynuz düşer.'),
  ('Erkeklerinde boynuz bulunmayan, bunun yerine uzun ve sivri üst köpek dişleri taşıyan ve karnındaki salgı bezi parfümcülükte kullanılmış olan hayvan hangisidir?', 'Misk geyiği', ['Ren geyiği', 'Alageyik', 'Sığın'], 'Misk geyiklerinin erkeklerinde boynuz yoktur; uzun köpek dişleri ve misk denen kokulu salgıyı üreten bezleri vardır.'),
  ('Güneydoğu Asya\'da yaşayan, kısa boynuzlu, uzun köpek dişli ve tehlikede köpek havlamasını andıran sesler çıkaran küçük geyik hangisidir?', 'Muntjak', ['Sığın', 'Kuzey Amerika wapitisi', 'Misk geyiği'], 'Muntjaklar \'havlayan geyik\' olarak da bilinir; tehlike hissettiklerinde köpek havlamasına benzer alarm sesleri çıkarırlar.'),
  ('Orta Asya bozkırlarında yaşayan sayga antilobunun iri ve sarkık burnunun olası işlevlerinden biri hangisidir?', 'Tozu süzmek ve soğuk havayı ısıtmak', ['Toprağı kazıp bitki köklerini bulmak', 'Ağaç dallarını kavrayıp aşağı çekmek', 'Suyu emip uzun süre depolamak'], 'Saygaların burnu içerdiği kıvrımlar ve bezlerle sürü hareketinde kalkan tozu tutar, kışın da solunan dondurucu havayı akciğere ulaşmadan ısıtır.'),
  ('Doğu Afrika\'da yaşayan küçük dikdik antiloplarının sosyal yaşamı hakkında hangisi doğrudur?', 'Çoğunlukla kalıcı çiftler hâlinde yaşarlar', ['Binlerce bireylik göçmen sürüler oluştururlar', 'Dişiler yalnız, erkekler büyük gruplar hâlinde yaşar', 'Kraliçe ve işçilerden oluşan koloniler kurarlar'], 'Dikdikler toynaklılar arasında tek eşlilik örneği olarak bilinir; çift, gözlerinin önündeki bezlerin salgısı ve dışkı yığınlarıyla ortak bölgesini işaretler.'),
  ('Etçiller takımında üst çenedeki son küçük azı dişi ile alt çenedeki ilk azı dişinin makas gibi birbirine sürtünerek eti kesmesini sağlayan dişlere ne ad verilir?', 'Karnasiyal dişler', ['Uzun köpek dişleri', 'Ön kesici dişler', 'Kalıcı süt dişleri'], 'Karnasiyal (parçalayıcı) dişler etçillerin ayırt edici özelliğidir; makas gibi çalışarak eti ve kirişi keser.'),
  ('Bir köpek kemik kemirirken başını yana çevirip ağzının yan tarafını kullanır. Bunun nedeni nedir?', 'Kesici azıların yanda olması', ['Ön kesici dişlerinin hiç bulunmaması', 'Dilinin ağzın bir yanına yerleşmiş olması', 'Kemiğin tadını yalnız yan dişleriyle alabilmesi'], 'Etçillerin eti ve kemiği kesen güçlü karnasiyal dişleri ağzın yan kısmında yer alır; köpek bu yüzden sert parçaları ağzının yanıyla çiğner.'),
  ('Ayılar ve insanlar gibi yürürken tüm ayak tabanını yere basan hayvanlar için hangi terim kullanılır?', 'Plantigrad', ['Dijitigrad', 'Unguligrad', 'Saltatoryal'], 'Plantigrad hayvanlar topuk dahil bütün tabana basar; bu, dengeli ve güçlü bir duruş sağlar ama hız açısından parmak üstünde yürümekten daha az verimlidir.'),
  ('Etçiller takımının modern sınıflandırmada iki büyük alt gruba ayrıldığı kabul edilir. Bu gruplar hangi hayvanların akrabalığına göre adlandırılmıştır?', 'Kedi ve köpek benzerleri', ['Karada ve denizde yaşayan etçiller', 'Gece ve gündüz avlanan etçiller', 'Kuyruklu ve kuyruksuz etçiller'], 'Etçiller kedigiller, sırtlanlar ve mangustları içeren kedi benzerleri (Feliformia) ile köpekgiller, ayılar, foklar ve sansargilleri içeren köpek benzerleri (Caniformia) olarak ikiye ayrılır.'),
  ('Avrasya ve Afrika\'da yaşayan, kurttan küçük, sürü yerine çoğunlukla çiftler hâlinde yaşayıp hem avlanan hem leş yiyen köpekgil hangisidir?', 'Altın çakal', ['Kızıl tilki', 'Rakun köpeği', 'Afrika yaban köpeği'], 'Altın çakal Türkiye dahil geniş bir bölgede yaşar; genellikle tek eşli çiftler ve onların yavrularından oluşan aile grupları hâlinde görülür.'),
  ('Avustralya\'nın dingosu hakkında hangisi doğrudur?', 'İnsanlarla gelip yabanıllaşmış bir köpektir', ['Avustralya\'ya özgü keseli bir etçildir', 'Tazmanya kaplanının doğrudan torunudur', 'Kıtaya buzul çağında kara köprüsüyle yürüyerek gelmiştir'], 'Dingo, birkaç bin yıl önce insanlarla Avustralya\'ya getirilmiş evcil köpek soyundan gelir; plasentalı bir köpekgildir.'),
  ('Kızıl tilkinin karın altındaki fareyi havaya sıçrayıp tepeden dalarak yakalaması hangi avlanma tekniğidir?', 'Fare atlayışı', ['Yuva ağzında pusu kurma', 'Uzun mesafeli kovalama', 'Sürüyle kuşatıp sıkıştırma'], 'Tilki, karın altındaki kemirgenin sesini işitip yerini kestirir; ardından yüksek bir kavisle sıçrayıp ön ayaklarıyla avı karın içinde bastırır.'),
  ('Leopar ile jaguar benzer benekli desenlere sahiptir. Jaguarı leopardan ayırmak için hangi özelliğe bakılır?', 'Jaguarın rozetleri içi noktalıdır', ['Jaguarın benekleri yalnızca kuyruğundadır', 'Leoparın rozetleri çok daha büyüktür ve içi noktalıdır', 'Jaguarın kürkü çizgilidir'], 'Jaguarın iri rozetlerinin ortasında genellikle bir ya da birkaç küçük benek bulunur; leoparın rozetleri daha küçük ve içi boştur. Jaguar ayrıca daha iri yapılıdır.'),
  ('Kulaklarının ucundaki uzun siyah püskülleriyle tanınan, Türkiye\'de karakulak adıyla bilinen ve havada uçan kuşları sıçrayarak yakalayabilen kedi hangisidir?', 'Karakal', ['Serval', 'Ocelot', 'Yaban kedisi'], 'Karakal (karakulak) Afrika, Orta Doğu ve Türkiye\'nin güney kesimlerinde yaşar; güçlü arka bacaklarıyla birkaç metre yükseğe sıçrayabilir.'),
  ('Bir kedinin ilginç bir koku aldıktan sonra üst dudağını kaldırıp ağzı yarı açık bir süre beklemesine ne ad verilir?', 'Flehmen', ['Mırlama', 'Yoğurma', 'Esneme refleksi'], 'Flehmen tepkisinde koku molekülleri ağız tavanındaki Jacobson (vomeronazal) organına yönlendirilir; bu organ özellikle feromonları algılar.'),
  ('Kaplanların her bireyde farklı olan çizgileri hakkında hangisi doğrudur?', 'Çizgi deseni derinin kendisinde de görülür', ['Çizgiler yalnızca yetişkinlikte ortaya çıkar', 'Bütün kaplanların deseni aynıdır', 'Çizgiler her yıl değişir'], 'Kaplanların çizgileri parmak izi gibi bireye özgüdür; kıllar tıraşlansa bile koyu desen deride görülmeye devam eder.'),
  ('Afrika savanında yaşayan ve kedigiller içinde vücuduna oranla en uzun bacaklara ve büyük kulaklara sahip olan, kemirgenleri sesle bulan tür hangisidir?', 'Serval', ['Karakal', 'Leopar', 'Kara ayaklı kedi'], 'Serval uzun bacakları ve büyük kulaklarıyla uzun otlar arasında kemirgenlerin sesini dinler, sonra yüksek bir sıçrayışla avının üzerine iner.'),
  ('Kedigillerin çoğu yalnız yaşar. Bu durumun avlanma biçimleriyle ilişkisi en iyi hangi seçenekte açıklanır?', 'Pusu avcılığı tek başına daha etkilidir', ['Kediler türdeşlerinin kokusuna dayanamaz', 'Kedilerin sesle iletişim kurma yetenekleri yoktur', 'Kedi yavruları doğar doğmaz bağımsız yaşar'], 'Pusu avcılığı sessizlik ve gizlilik gerektirir; tek başına hareket eden avcı daha az fark edilir. Açık savanda yaşayan aslanlar ise bu genellemenin istisnasıdır.'),
  ('Güney Amerika\'da doğal olarak yaşayan tek ayı türü hangisidir ve adını nereden alır?', 'Gözlüklü ayı; yüzündeki halkalardan', ['Güneş ayısı; göğsündeki sarı lekeden', 'Tembel ayı; yavaş hareketlerinden', 'Kara ayı; tümüyle siyah kürkünden'], 'Gözlüklü ayı And Dağları\'nda yaşar; yüzündeki açık renkli halkalar gözlük izlenimi verir. Beslenmesinin büyük kısmı bitkiseldir.'),
  ('Ayıların beslenme biçimi bakımından türler arası farkı en doğru anlatan sıralama hangisidir?', 'En etçil kutup ayısı, en otçul dev pandadır', ['En etçil güneş ayısı, en otçul kutup ayısıdır', 'Bütün ayılar yalnızca etle beslenir', 'En etçil dev panda, en otçul bozayıdır'], 'Ayıların çoğu hepçildir; deniz buzu üzerinde fok avlayan kutup ayısı en etçil, neredeyse yalnız bambu yiyen dev panda ise en otçul uçtadır.'),
  ('Afrika ve Asya\'da yaşayan bal porsuğunun (ratel) saldırganlara karşı başlıca korunma özelliklerinden biri hangisidir?', 'Kalın ve gevşek derisi', ['Sırtında zehirli dikenler taşıması', 'Kuyruğundan zehirli sıvı püskürtmesi', 'Sert bir kabuğun içine çekilebilmesi'], 'Bal porsuğunun derisi kalın ve gevşektir; bir avcı onu ensesinden yakalasa bile deri içinde dönüp ısırabilir.'),
  ('Avrupa porsuğunun yaşam biçimiyle ilgili hangisi doğrudur?', 'Kuşaklarca kullanılan yer altı yuvalarında yaşar', ['Yalnızca yaşlı ağaçların kovuklarında yaşar', 'Göl kıyısında dallardan baraj kurup yaşar', 'Mevsimlere göre sürekli göç eden bir sürü hayvanıdır'], 'Porsuklar çok sayıda giriş ve odadan oluşan yer altı yuvalarını onlarca yıl, hatta yüzyıllar boyunca kuşaktan kuşağa kullanabilir.'),
  ('Deniz samurunun soğuk sularda vücut ısısını koruması diğer deniz memelilerinden hangi yönüyle farklıdır?', 'Yağ yerine yoğun kürküne dayanır', ['Gün boyu sürekli titreyerek ısı üretir', 'Kanında donmayı önleyen özel proteinler taşır', 'Suda değil yalnızca karada uyuyabilir'], 'Deniz samurunun kalın yağ tabakası yoktur; içine hava hapseden son derece yoğun kürkü ve yüksek metabolizması onu sıcak tutar.'),
  ('Kakım ile gelinciği kışın bile ayırt etmeye yarayan özellik hangisidir?', 'Kakımın kuyruk ucunun siyah kalması', ['Gelinciğin kışın tümüyle siyaha dönmesi', 'Kakımın kuyruğunun neredeyse hiç olmaması', 'Gelinciğin kulaklarının uzun püsküllü olması'], 'Kakım kışın beyaza dönse de kuyruk ucu siyah kalır; daha küçük olan gelinciğin kuyruğu ise kısadır ve siyah uç taşımaz.'),
  ('Rakunların besinlerini suya batırıp elleriyle ovalaması için günümüzde en çok kabul gören açıklama nedir?', 'Islaklık dokunma duyarlılığını artırır', ['Besindeki tuzu gidermek', 'Tükürük salgılayamadıkları için yiyeceği ıslatmak', 'Besini temizleyip hastalıktan korunmak'], 'Rakunun ön patileri çok sayıda dokunma reseptörü içerir; ıslak ortamda bu reseptörler daha duyarlı hâle gelir ve hayvan besini adeta elleriyle inceler.'),
  ('Sırtlanlar görünüş olarak köpeklere benzer. Evrimsel akrabalık bakımından hangisi doğrudur?', 'Kedi benzeri etçillere yakındırlar', ['Köpekgillerin bir alt familyasıdırlar', 'Ayılarla aynı familyada yer alırlar', 'Etçil değil, primatların uzak akrabasıdırlar'], 'Sırtlangiller etçillerin kedi benzerleri (Feliformia) kolundadır; köpeklere benzerlikleri benzer yaşam biçiminden kaynaklanır.'),
  ('Bir doğa gezisinde savanda bembeyaz renkte, kireçli dışkılar görülüyor. Bu dışkıların büyük olasılıkla hangi hayvana ait olduğu ve neden beyaz olduğu hangisidir?', 'Sırtlana; yediği kemiklerden', ['Zebraya; yediği kuru ve sert otlardan', 'Aslana; içtiği sudaki tuzlardan', 'Gergedana; yediği ağaç kabuklarından'], 'Sırtlanlar güçlü çeneleriyle kemikleri kırıp sindirir; kemik minerallerinin kalıntısı dışkının kuruyunca beyaz görünmesine yol açar.'),
  ('Kemirgenlerde kesici dişler ile azı dişleri arasında köpek dişi yoktur ve geniş bir boşluk bulunur. Bu boşluğun hayvana sağladığı kolaylık nedir?', 'Dudaklar boşluğa kıvrılarak kemirilen talaşın ağza girmesini önler', ['Boşlukta besin depolanarak kışın yenir', 'Boşluktan soluk alınarak suda kalınır', 'Boşluk sesi yükseltip iletişimi kolaylaştırır'], 'Diastema denen bu boşluğa dudaklar içeri kıvrılabilir; böylece kemirgen ağzı kapalıyken önden kemirir ve yenmeyen parçalar ağza girmez.'),
  ('Çıplak köstebek faresi küçük bir kemirgen olmasına karşın hangi özelliğiyle araştırmacıların ilgisini çeker?', '30 yılı aşabilen olağan dışı uzun ömrü', ['Kuşlar gibi uçabilmesi', 'Fotosentez yapan derisi', 'Yılda bir kez doğurması ve kesesinde taşıması'], 'Fare boyutundaki çoğu kemirgen birkaç yıl yaşarken çıplak köstebek faresi otuz yılın üzerinde yaşayabilir ve kansere çok dirençli olduğu bilinir.'),
  ('And Dağları\'nda yaşayan çinçillaların kürklerini temizlemek için yaptığı davranış hangisidir?', 'İnce volkanik tozda yuvarlanmak', ['Akarsuda uzun süre yıkanmak', 'Birbirini yalamak', 'Ağaç reçinesine sürtünmek'], 'Çinçilla kürkü çok yoğundur ve ıslanınca zor kurur; bu yüzden yağı ve nemi gidermek için ince tozda kum banyosu yapar.'),
  ('Kunduzların kesici dişlerinin turuncu renkli olmasının nedeni nedir?', 'Dişin ön yüzündeki minede demir bulunması', ['Yedikleri ağaç kabuğunun boyaması', 'Diş etlerinden kan sızması', 'Dişlerin içinin boş olması'], 'Kunduz dişinin ön yüzündeki mine demir içerir; bu hem turuncu rengi verir hem de dişi asit ve aşınmaya karşı daha dayanıklı yapar.'),
  ('Türkiye\'nin güneydoğusunda da yaşayan araptavşanları (jerboa) hakkında hangisi doğrudur?', 'Uzun arka bacaklarıyla sıçrayan kemirgenlerdir', ['Tavşanımsılar takımındandır', 'Keseli memelilerdir', 'Gündüz etkin otlayıcılardır'], 'Araptavşanları adlarına karşın tavşan değil kemirgendir; çöl ve bozkırda geceleri uzun arka bacaklarıyla kanguru gibi sıçrayarak hareket eder.'),
  ('Kuzey bölgelerinde lemming sayısının birkaç yılda bir aşırı artıp ardından çökmesi hangi canlıların popülasyonunu da dalgalandırır?', 'Kutup tilkisi ve kar baykuşu gibi avcılarının', ['Ren geyiklerinin boynuz uzunluğunun', 'Kutup ayılarının kürk renginin', 'Balinaların göç yolunun'], 'Lemming bolluğu yıllarında onları avlayan kutup tilkisi ve kar baykuşu gibi türler daha çok yavru yetiştirir; lemmingler azalınca avcı popülasyonları da düşer.'),
  ('Avrupa tavşanı ile yaban tavşanının yeni doğan yavruları karşılaştırıldığında hangisi doğrudur?', 'Yaban tavşanı yavruları gözleri açık ve kürklü doğar', ['Avrupa tavşanı yavruları doğar doğmaz koşabilir', 'İkisinin yavruları da yumurtadan çıkar', 'Yaban tavşanı yavruları tüysüz ve kör doğar'], 'Avrupa tavşanı yavrularını yuvada kör ve tüysüz doğurur; açıkta yuva yapan yaban tavşanının yavruları ise kürklü, gözleri açık ve kısa sürede hareket edebilir.'),
  ('Dağlık bölgelerin kayalıklarında yaşayan pikaların yazın kuruttukları otları kayalar arasına yığmasının nedeni nedir?', 'Kış uykusuna yatmadıkları için kış boyu besin sağlamak', ['Yuvayı yalıtmak için dışkılarını örtmek', 'Avcıları koku ile şaşırtmak', 'Yavrulara oyun alanı hazırlamak'], 'Pikalar kış uykusuna yatmaz; yazın topladıkları ot yığınları kar altındaki uzun kış boyunca başlıca besin kaynaklarıdır.'),
  ('Pikalar ve tavşanlar aynı takımdadır. Pikaları tavşanlardan ayıran görünüş özelliği hangisidir?', 'Kısa, yuvarlak kulaklar ve dışarıdan görünmeyen kuyruk', ['Uzun kuyruk ve sivri kulaklar', 'Dikenli kürk', 'Uzun arka bacaklar ve büyük kulaklar'], 'Pikalar küçük, yuvarlak kulaklı ve kuyruğu görünmeyen hayvanlardır; tavşanların uzun kulakları ve sıçramaya uygun uzun arka bacakları onlarda yoktur.'),
  ('Ağırlığı yalnızca iki gram dolayında olan ve kütlece bilinen en küçük memelilerden sayılan hayvan hangisidir?', 'Etrüsk sivri faresi', ['Ev faresi', 'Fındık faresi', 'Cüce tarla faresi'], 'Akdeniz çevresinde de yaşayan Etrüsk sivri faresi yaklaşık 1,8–2 gram ağırlığıyla kütlece en küçük memelilerdendir; Tayland\'daki eşek arısı yarasası da benzer boyuttadır.'),
  ('Küçük sivri farelerin birkaç saat besinsiz kaldığında ölebilmesinin temel nedeni nedir?', 'Küçük gövdelerinin çok hızlı ısı kaybetmesi ve metabolizmalarının çok yüksek olması', ['Midelerinin besin depolayamayacak kadar küçük olması', 'Dişlerinin sürekli uzaması', 'Su içemedikleri için yalnızca besinden su almaları'], 'Hacmine göre yüzey alanı büyük olan küçük memeliler hızla ısı kaybeder; bunu karşılamak için çok yüksek metabolizmayla neredeyse sürekli beslenmek zorundadır.'),
  ('Bazı sivri fare türlerinde yavruların yuvadan taşınırken birbirinin kuyruk dibini ısırarak annenin arkasında zincir oluşturmasına ne ad verilir?', 'Kervan davranışı', ['Sürü göçü', 'Tımar', 'Oyun dövüşü'], 'Beyaz dişli sivri farelerde görülen kervan davranışında yavrular ağızlarıyla öndekine tutunur; böylece anne bütün yavruları tek seferde güvenli bir yere taşır.'),
  ('Yarasaların çoğunun yılda yalnızca bir yavru doğurması, yaşam stratejileri hakkında ne gösterir?', 'Az ama iyi bakılan yavru yetiştirdiklerini', ['Hızla çoğalıp kısa yaşadıklarını', 'Yavrularını hiç emzirmediklerini', 'Yumurta bıraktıklarını'], 'Uzun ömür, az yavru ve uzun bakım süresi K-stratejisinin özellikleridir; bu nedenle yarasa popülasyonları kayıplardan sonra yavaş toparlanır.'),
  ('Nalburunlu yarasaların burnundaki at nalı biçimli deri yaprağının işlevi nedir?', 'Burundan çıkan sesleri yönlendirmek', ['Kan emmek için deriyi kesmek', 'Çiçeklerden nektar toplamak', 'Kış uykusunda burnu ısıtmak'], 'Nalburunlu yarasalar ekolokasyon seslerini ağızdan değil burundan çıkarır; burun yaprağı bu sesleri dar bir demet hâlinde odaklar.'),
  ('Böcekçil bir yarasa avına yaklaştıkça ses darbelerinin sıklığı nasıl değişir?', 'Saniyedeki darbe sayısı çok artar', ['Ses tamamen kesilir', 'Darbeler seyrekleşir', 'Sesin frekansı insan duyma aralığına iner'], 'Avı ararken seyrek olan çağrılar, son yaklaşmada saniyede yüzlerce darbelik bir \'besleme vızıltısına\' dönüşür; böylece avın konumu çok sık güncellenir.'),
  ('Yarasaların arka bacaklarının anatomisinde diğer memelilerden farklı olan özellik hangisidir?', 'Dizleri geriye ve dışa dönüktür', ['Arka bacakları hiç yoktur', 'Arka bacakları perdeli yüzgeçtir', 'Arka bacaklarında toynak bulunur'], 'Yarasalarda arka bacaklar dönmüş durumdadır ve dizler geriye bakar; bu yapı baş aşağı asılmaya ve kanat zarını germeye uygundur.'),
  ('Yeni Dünya (Amerika) maymunlarını Eski Dünya (Afrika ve Asya) maymunlarından burunlarına bakarak nasıl ayırabiliriz?', 'Yeni Dünya maymunlarında burun delikleri yana bakar', ['Yeni Dünya maymunlarının burnu hortum gibi uzundur', 'Eski Dünya maymunlarında yalnız bir burun deliği vardır', 'Eski Dünya maymunlarının burun delikleri yukarı bakar'], 'Yeni Dünya maymunlarının (geniş burunlular) burun delikleri birbirinden uzak ve yana açılır; Eski Dünya maymunları ile insansılarda (dar burunlular) ise birbirine yakın ve aşağı bakar.'),
  ('Avrupa\'da yaban hayatında yaşayan tek maymun popülasyonu hangisidir?', 'Cebelitarık\'taki Berberi makakları', ['İtalya\'daki Japon makakları', 'Türkiye\'deki Rhesus makakları', 'Yunanistan\'daki şebekler'], 'Kuzey Afrika kökenli Berberi makakları Cebelitarık Kayası\'nda yaşar ve Avrupa\'nın tek serbest yaşayan maymun popülasyonu olarak bilinir.'),
  ('Marmoset ve tamarinlerin üremesinde dikkat çeken özellik hangisidir?', 'İkiz doğum ve babanın yavru taşıması', ['Yumurta bırakıp kuluçkaya yatmaları', 'Yavrularını karınlarındaki kesede taşımaları', 'Yalnızca kış uykusu sırasında doğurmaları'], 'Bu küçük Güney Amerika maymunlarında ikiz doğum yaygındır; yavruların taşınmasında baba ve grubun diğer üyeleri de anneye yardım eder.'),
  ('Güneydoğu Asya\'da yaşayan tarsiyelerin beslenmesi hakkında hangisi doğrudur?', 'Tamamen hayvansal besinle beslenirler', ['Yalnızca genç bambu filizleriyle beslenirler', 'Ağaç özsuyu ve çiçek nektarıyla beslenirler', 'Yalnızca olgun meyvelerle beslenirler'], 'Tarsiyeler tamamen etçil olan tek primatlardır; geceleri iri gözleri ve sıçrama yetenekleriyle böcek, kertenkele ve küçük kuşları yakalarlar.'),
  ('Halka kuyruklu lemur erkeklerinin çiftleşme döneminde kuyruklarına bilek bezlerinin salgısını sürüp rakiplerine doğru sallamasına ne ad verilir?', 'Koku dövüşü', ['Kur dansı', 'Tımar zinciri', 'Alarm çağrısı'], 'Bu \'koku dövüşlerinde\' erkekler kokulu kuyruklarını rakiplerine doğru sallar; dövüş çoğu zaman fiziksel temasa varmadan biter.'),
  ('Lemur topluluklarının çoğunda sosyal yapıyla ilgili dikkat çeken özellik hangisidir?', 'Dişilerin erkeklere baskın olması', ['Grupların yalnız erkeklerden oluşması', 'Bütün bireylerin yalnız yaşaması', 'Grupları en yaşlı erkeğin yönetmesi'], 'Halka kuyruklu lemur dahil birçok lemur türünde dişiler besine öncelikli erişir ve erkeklere baskındır; bu, primatlar arasında dikkat çekici bir durumdur.'),
  ('Tek eşli yaşayan jibon çiftlerinin sabahları birlikte söylediği uzun şarkıların işlevi nedir?', 'Çift bağı ve bölge bildirimi', ['Böcek avlarını sesle sersemletmek', 'Yaklaşan yağmuru grup üyelerine haber vermek', 'Yavruları uyandırıp beslenmeye çağırmak'], 'Jibon düetleri çiftin birlikteliğini ve bölgenin sahibini komşu gruplara ilan eder; ses ormanda kilometrelerce uzağa yayılır.'),
  ('Batı Afrika ormanlarında yaşayan erkek mandrilin yüzündeki parlak kırmızı ve mavi renklerin yoğunluğu neyle ilişkilidir?', 'Erkeğin sosyal konumu', ['Yediği meyvenin rengi', 'Havadaki nem oranı', 'Yaşadığı ağacın yüksekliği'], 'Baskın mandril erkeklerinin yüz renkleri daha canlıdır; renk yoğunluğu testosteron düzeyiyle bağlantılıdır ve dişilere ve rakiplere sinyal verir.'),
  ('Madagaskar\'da yaşayan sifakaların yerde iki ayak üstünde yan yan sıçrayarak ilerlemesinin nedeni nedir?', 'Bacaklarının dikey sıçramaya uyumlu olması', ['Ön bacaklarının hiç olmaması', 'Kuyruklarının yere değmemesi gerektiği', 'Kumun çok sıcak olması'], 'Sifakalar ağaç gövdeleri arasında dikey tutunup sıçramaya uyumludur; yere indiklerinde de uzun arka bacaklarıyla yanlamasına sıçrar ve bu hareket dansa benzetilir.'),
  ('Soğukta ya da korktuğunda bir kedinin kürkünün kabarmasını sağlayan yapı hangisidir?', 'Kıl kökündeki küçük düz kaslar', ['Deri altındaki şişebilen yağ bezleri', 'Kılın ucundaki kasılabilen sinir lifleri', 'Derideki sıvı dolu ter bezleri'], 'Her kıl folikülüne bağlı küçük kaslar kasılınca kıl dikleşir; kabaran kürk daha çok hava tutarak yalıtımı artırır, tehdit anında da hayvanı iri gösterir.'),
  ('Birçok memelinin kürkünde, alttaki ince ve sık yün katmanının üstünde daha uzun ve kalın kıllar bulunur. Bu dış kılların başlıca işlevi nedir?', 'Alt yünü ıslanmaktan korumak', ['Vücut ısısını dışarı atmak', 'Ses dalgalarını algılamak', 'Avları zehirlemek'], 'Uzun koruyucu kıllar suyu ve kiri iterek alt kürkün kuru kalmasını sağlar; ısı yalıtımının büyük kısmını ise havayı hapseden alt yün sağlar.'),
  ('Meme bezlerinin evrimsel kökeni hakkında en çok kabul gören görüş hangisidir?', 'Deri bezlerinden evrimleştikleri', ['Akciğer dokusundan geliştikleri', 'Sindirim kanalının bir kesesi oldukları', 'Kas dokusunun salgı yapmaya başladığı'], 'Meme bezleri derideki ter bezine benzer bezlerin değişmesiyle evrimleşmiştir; ornitorenkte memenin olmayıp sütün deriden sızması bu kökene uyumludur.'),
  ('Kunduzların kuyruk dibindeki bezlerden salgılanan ve bölge işaretlemede kullanılan madde hangisidir?', 'Kastoreum', ['Misk', 'Ambergris', 'Lanolin'], 'Kastoreum kunduzların koku işaretinde kullandığı salgıdır; misk misk geyiğinden, ambergris ispermeçet balinasından, lanolin koyun yününden elde edilir.'),
  ('Geyiklerin gözlerinin ön köşesindeki çukur bezleri dallara sürtmesinin amacı nedir?', 'Kokuyla varlığını bildirmek', ['Gözlerini temizlemek', 'Boynuzlarını bilemek', 'Dalı kırıp yaprağa ulaşmak'], 'Göz önü bezlerinin salgısı bireye özgü koku taşır; geyikler bu salgıyı dallara sürerek varlıklarını ve bölgelerini diğer geyiklere bildirir.'),
  ('Bir köpeğin diş formülü her çene yarısı için üstte 3 kesici, 1 köpek, 4 küçük azı, 2 azı; altta 3 kesici, 1 köpek, 4 küçük azı, 3 azı şeklindedir. Köpeğin toplam diş sayısı kaçtır?', '42', ['32', '36', '44'], 'Bir yarıda üstte 3+1+4+2=10, altta 3+1+4+3=11 diş vardır; iki yarı için (10+11)×2=42 eder.'),
  ('Erişkin bir kedinin diş formülü üst çene yarısında 3 kesici, 1 köpek, 3 küçük azı, 1 azı; alt çene yarısında 3 kesici, 1 köpek, 2 küçük azı, 1 azı şeklindedir. Kedide toplam kaç diş bulunur?', '30', ['28', '32', '42'], 'Üst yarı 3+1+3+1=8, alt yarı 3+1+2+1=7 eder; (8+7)×2=30 diş. Kedilerin et kesmeye uygun kısa yüzü, köpeğe göre daha az diş taşımasıyla uyumludur.'),
  ('Tavşanın diş formülü üstte 2-0-3-3, altta 1-0-2-3 şeklindedir (kesici-köpek-küçük azı-azı). Bu formülden aşağıdaki sonuçlardan hangisine ulaşılır?', 'Köpek dişi yoktur; toplam 28 diş vardır', ['Köpek dişi vardır; toplam 32 diş bulunur', 'Alt çenede hiç azı dişi bulunmaz', 'Üst çenenin her yarısında tek kesici vardır'], 'Köpek dişi sayısı 0\'dır; üst yarı 2+0+3+3=8, alt yarı 1+0+2+3=6 eder ve toplam (8+6)×2=28 diş bulunur.'),
  ('Bir çocuğun süt dişleri her çene yarısında 2 kesici, 1 köpek ve 2 azıdan oluşur. Çocuğun toplam süt dişi sayısı ile erişkin insanın 32 kalıcı dişi arasındaki fark kaçtır?', '12', ['8', '10', '16'], 'Süt dişi sayısı (2+1+2)×4=20\'dir; 32−20=12 kalıcı diş, süt dişlerinin yerine değil, onların arkasından ek olarak çıkar.'),
  ('Ölü bulunan bir ayının ya da geyiğin yaşını belirlemek için dişin kökünden alınan ince kesitte sayılan yapı nedir?', 'Sementteki yıllık halkalar', ['Minedeki kahverengi renk lekeleri', 'Diş sinirinin kökteki dalları', 'Dişteki ince çatlakların sayısı'], 'Diş kökünü saran sement her yıl biri yaz, biri kış olmak üzere farklı yoğunlukta katmanlar oluşturur; bu halkalar ağaç halkaları gibi sayılarak yaş tahmin edilir.'),
  ('Ornitorenk yavrularında küçük dişler bulunur ama erişkinlerde dişler kaybolur. Erişkin ornitorenk avını nasıl ezer?', 'Çenelerindeki keratin plakalarla', ['Midesindeki taşlarla', 'Gagasının içindeki kemik dikenlerle', 'Avını bütün olarak yutup hiç ezmeden'], 'Erişkin ornitorenkte dişlerin yerini sert keratin plakalar alır; yakaladığı solucan ve böcek larvalarını bu plakalar arasında öğütür.'),
  ('Bir öğrenci \'diş sayısı arttıkça hayvan daha etçildir\' diye bir genelleme yapıyor. Hangi karşılaştırma bu genellemeyi çürütür?', 'Kedilerin köpeklerden az dişli ama daha etçil olması', ['Kedinin köpekten daha fazla dişe sahip olması', 'Otçulların azı dişi taşımaması', 'İnsanın erişkinlikte 44 dişe sahip olması'], 'Kedigiller neredeyse tamamen etçildir ama köpekgillerden daha az dişe sahiptir; köpekgiller ise daha hepçil beslenir. Yani diş sayısı beslenme tipini tek başına belirlemez.'),
  ('Bir inek ile bir atın selülozu mikroplar yardımıyla sindirdiği yerler karşılaştırıldığında hangisi doğrudur?', 'İnekte midede, atta kalın bağırsakta', ['İkisinde de yalnızca ağızda ve yemek borusunda', 'İnekte kalın bağırsakta, atta ise midede', 'İkisinde de karaciğer ve safra kesesinde'], 'İnek mikrobik mayalanmayı midesinin ön bölmelerinde yapar; at ise tek midelidir ve mayalanma iri kör bağırsağı ile kalın bağırsağında gerçekleşir.'),
  ('Arka bağırsakta mayalanma yapan bir at, aynı kalitede otla beslenen bir sığıra göre genellikle neden daha fazla ot yemek zorundadır?', 'Mikrobik besinin bir kısmı emilmeden atılır', ['Atın midesi hiçbir koşulda asit salgılamaz', 'Atlar otu dişleriyle çiğneyemeden yutar', 'Atların bağırsağında hiç mikroorganizma yoktur'], 'Mayalanma emilimin ana yeri olan ince bağırsaktan sonra gerçekleştiği için mikrop proteinlerinin önemli bir kısmı kaybolur; at bunu daha hızlı ve daha çok yiyerek dengeler.'),
  ('Afrika ve Asya\'da yaşayan bazı yaprak yiyen maymunların (kolobuslar ve languurlar) sindirim sistemi hangi yönüyle geviş getirenlere benzer?', 'Bölmeli ve mikroplu bir mideleri olması', ['Birbirine paralel dört ayrı yemek borusuna sahip olmaları', 'Yediklerini kusup ertesi gün yeniden yemeleri', 'Hiç ince bağırsaklarının bulunmaması'], 'Kolobus maymunlarının midesi bölmelidir ve yaprakları mayalayan mikroplar barındırır; bu, primatlar arasında ön midede mayalanmanın bir örneğidir.'),
  ('Bir vampir yarasa bir gecede vücut ağırlığına yakın kan içebilir. Uçuşa hemen geçebilmesini sağlayan böbrek özelliği nedir?', 'Kanın suyunu hızla idrarla atması', ['İçtiği kanı kanat zarlarında depolaması', 'İçtiği kanın yarısını hemen kusarak boşaltması', 'Kanın suyunu akciğerlerinde buharlaştırması'], 'Vampir yarasa beslenirken kanın plazma suyunu çok hızlı idrara dönüştürür; böylece ağırlığı azalır ve uçabilir. Gün içinde ise proteince zengin besini sindirirken su tasarrufu yapar.'),
  ('Fare gibi küçük memelilerin kalbi dakikada yüzlerce kez atarken bir filin kalbi dakikada yalnızca 30 kadar atar. Bu fark en iyi nasıl açıklanır?', 'Küçüklerin kütle başına metabolizmasının yüksek olması', ['Fillerin kanının daha koyu ve ağır olması', 'Farelerin kalbinin dört değil iki odacıklı olması', 'Fillerin dinlenirken neredeyse hiç oksijen kullanmaması'], 'Küçük memeliler birim kütle başına daha çok ısı kaybeder ve daha hızlı metabolizmaya sahiptir; bu yüksek oksijen talebini karşılamak için kalpleri çok hızlı çalışır.'),
  ('Kar üzerinde saatlerce duran bir kurdun ayakları buz kadar soğuk olsa da vücut ısısı fazla düşmez. Bunu sağlayan, bacaklardaki atar ve toplardamarların yan yana uzanmasıyla oluşan düzene ne ad verilir?', 'Ters akımlı ısı değişimi', ['Kahverengi yağ yakımı', 'Dalma refleksi', 'Mevsimsel kış uykusu'], 'Bacağa inen sıcak atardamar kanı, yukarı çıkan soğuk toplardamar kanını ısıtır; böylece ısı vücut içinde tutulur ve ayaktan dışarıya az ısı kaybedilir.'),
  ('Alaska\'daki Kuzey Kutbu yer sincabının kış uykusunda olağan dışı kabul edilen özelliği hangisidir?', 'Vücut ısısının sıfırın altına inmesi', ['Kış boyunca her gün yemek yemesi', 'Vücut sıcaklığının 45 °C\'ye yükselmesi', 'Kış uykusunu yalnızca birkaç saat sürdürmesi'], 'Kuzey Kutbu yer sincabının vücut sıcaklığı kış uykusunda yaklaşık −3 °C\'ye kadar inebilir; vücut sıvıları aşırı soğumuş hâlde kalır ama donmaz.'),
  ('Bazı küçük memeliler ve yarasalar her gün birkaç saat vücut ısılarını düşürürken, dağ sıçanları haftalarca süren bir derin uyku dönemine girer. Bu iki durum arasındaki temel fark nedir?', 'Birinin günlük, ötekinin mevsimlik olması', ['Birincisi yalnız yazın, ikincisi yalnız ilkbaharda olur', 'İkisi de aynı süre sürer, yalnız adları farklıdır', 'Birincisinde vücut ısısı yükselir, ikincisinde değişmez'], 'Günlük torpor birkaç saat sürer ve çoğu zaman her gün tekrarlanır; kış uykusu ise günler-haftalar süren derin torpor dönemlerinden oluşan mevsimsel bir durumdur.'),
  ('Madagaskar\'daki şişman kuyruklu cüce lemur hangi özelliğiyle dikkat çeker?', 'Kış uykusuna yatan bir primat olması', ['Kuyruğundaki bezlerde zehir taşıması', 'Deri zarıyla süzülebilen tek primat olması', 'Yalnızca mangrovlarda su içinde yaşaması'], 'Şişman kuyruklu cüce lemur, kuyruğunda depoladığı yağla kurak ve kıt kışı aylarca uykuda geçirir; bilinen ilk kış uykusuna yatan primattır.'),
  ('Atlar yoğun egzersizde çok terler ve terleri sürtünme olan yerlerde beyaz köpük oluşturur. Bu köpürmenin nedeni nedir?', 'Terdeki deterjan benzeri bir protein', ['Terin içine karışan sabun kalıntıları', 'Derinin içindeki hava kabarcıkları', 'Terin çok soğuk olması'], 'At terinde latherin adlı bir protein bulunur; bu protein terin yağlı kıllara yayılmasını kolaylaştırarak buharlaşmayı artırır ve köpük oluşmasına yol açar.'),
  ('Vücut kütlesi aynı olan iki memeliden biri yuvarlak ve tıknaz, diğeri ince ve uzun yapılıdır. Soğuk bir ortamda hangisinin daha az ısı kaybetmesi beklenir ve neden?', 'Tıknaz olan; hacmine göre yüzey alanı daha küçüktür', ['İnce olan; daha hızlı hareket eder', 'İnce olan; kanı daha hızlı dolaşır', 'İkisi eşit kaybeder; ısı kaybı yalnızca kürke bağlıdır'], 'Isı yüzeyden kaybedilir; aynı hacimde daha küçük yüzey alanına sahip yuvarlak bir beden daha az ısı kaybeder. Kutup memelilerinin tıknaz yapısı bunu yansıtır.'),
  ('Kış uykusuna hazırlanan bir dağ sıçanının yağ dokusunun hangi niteliği uyku sırasında enerji ihtiyacını karşılamaya özellikle uygundur?', 'Gram başına en çok enerjiyi vermesi', ['Suda çözünüp kanla taşınabilmesi', 'Hiç oksijen gerektirmeden yanması', 'Kas dokusundan daha ağır olması'], 'Yağ, gram başına karbonhidrat ve proteinden yaklaşık iki kat fazla enerji sağlar; bu nedenle uzun açlık dönemleri için en verimli depodur.'),
  ('Bir köpek sahibi, yeşil çimenlik bir alanda kırmızı top yerine mavi top kullanmaya karar veriyor. Bu tercihin mantığı nedir?', 'Köpek kırmızıyı yeşilden zor ayırır', ['Köpekler mavi rengi kokusundan ayırt edebilir', 'Kırmızı renk köpekleri saldırgan yapar', 'Mavi top çimenlikte daha uzağa yuvarlanır'], 'Köpeklerin iki renkli görüşünde kırmızı ile yeşil benzer görünür; mavi ise yeşil zeminde belirgin şekilde ayrışır.'),
  ('Afrika\'da yaşayan yarasa kulaklı tilkinin çok büyük kulaklarının başlıca işlevi nedir?', 'Toprak altındaki termit ve böceklerin sesini duymak', ['Kanat gibi kullanıp süzülmek', 'Yağmur suyunu toplamak', 'Avcılardan gizlenmek için gölge yapmak'], 'Yarasa kulaklı tilki çoğunlukla termit ve böceklerle beslenir; iri kulaklarıyla toprak altındaki böceklerin çıkardığı zayıf sesleri yakalar. Kulaklar ısı atımına da yardım eder.'),
  ('Ren geyiklerinin gözlerinin ultraviyole ışığı algılayabildiği bulunmuştur. Karla kaplı Arktik ortamında bu yetenek nasıl bir yarar sağlayabilir?', 'Liken ve kürkleri karda seçebilmek', ['Güneş yanığından korunmak', 'Gece göğündeki yıldızlarla yön bulmak', 'Buzun kalınlığını ölçmek'], 'Kar UV ışığı güçlü yansıtırken liken ve kurt kürkü UV\'yi emer; UV görebilen ren geyiği için bu nesneler beyaz zeminde koyu lekeler gibi belirginleşir.'),
  ('Memelilerin çoğundaki östrus döngüsü ile insan ve bazı primatlardaki adet döngüsü arasındaki temel fark nedir?', 'Östrusta rahim iç zarı dökülmez, geri emilir', ['Östrus döngüsü yalnızca erkeklerde görülür', 'Adet döngüsünde yumurtlama hiç olmaz', 'Östrus döngüsü ömürde yalnızca bir kez olur'], 'Adet döngüsünde döllenme olmazsa kalınlaşan rahim iç zarı kanamayla dökülür; östrus döngüsünde ise zar vücut tarafından geri emilir ve dişi yalnız kızgınlık döneminde çiftleşmeye isteklidir.'),
  ('Ilıman bölgelerdeki bazı yarasa türleri sonbaharda çiftleşir ama yavrular ilkbahar sonunda doğar. Bunu sağlayan mekanizma nedir?', 'Spermin kış boyu saklanması', ['Yavrunun kış boyunca kesede beslenmesi', 'Embriyonun yumurta kabuğunda beklemesi', 'Gebeliğin on iki ay sürmesi'], 'Bu yarasalarda dişi spermi kış uykusu boyunca canlı tutar; döllenme ve gelişme ilkbaharda uyanınca başlar, böylece yavru böceklerin bol olduğu döneme denk gelir.'),
  ('Kemirgenler ve kedilerin yavrularının gözleri kapalı ve az kıllı doğması ile yuva kullanmaları arasında nasıl bir ilişki vardır?', 'Yuva, az gelişmiş doğumu mümkün kılar', ['Yuvası olan türlerin yavruları her zaman prekosyaldir', 'Yuvadaki karanlık yavruların gözünü kapatır', 'İkisi arasında hiçbir anlamlı ilişki yoktur'], 'Korunaklı bir yuvası olan türler kısa gebelikle çok sayıda, az gelişmiş yavru doğurabilir; açık alanda doğan yavruların ise hemen hareket edebilmesi gerekir.'),
  ('Bir dişi memelide emzirme süresince yeniden kızgınlığa girmenin gecikmesi, tür için hangi bakımdan uyumsaldır?', 'Enerjinin mevcut yavruya ayrılması', ['Annenin hızla kilo almasını sağlar', 'Yavrunun daha erken sütten kesilmesini sağlar', 'Erkeklerin sürüden ayrılmasını sağlar'], 'Süt üretmek çok enerji ister; emzirme hormonlarının yumurtlamayı baskılaması, yeni gebeliği mevcut yavru belirli bir gelişmeye ulaşana kadar erteler.'),
  ('Şempanze topluluklarında bireylerin gün içinde küçük gruplara ayrılıp sonra yeniden bir araya gelmesiyle oluşan toplumsal düzene ne ad verilir?', 'Ayrılma-birleşme toplumu', ['Harem düzeni', 'Koloni yaşamı', 'Kast sistemi'], 'Ayrılma-birleşme (fission-fusion) düzeninde topluluk sabittir ama alt grupların bileşimi besin durumuna göre sürekli değişir; şempanze, örümcek maymunu ve fillerde görülür.'),
  ('Şempanzelerde gruptan ayrılıp başka bir topluluğa katılan eşey genellikle hangisidir?', 'Dişiler', ['Erkekler', 'Yalnız yaşlı erkekler', 'Yalnız yavrular'], 'Şempanzelerde erkekler doğdukları toplulukta kalıp aralarında ittifak kurar; ergenliğe ulaşan dişiler ise çoğunlukla komşu bir topluluğa göç eder.'),
  ('Doğal ortamdaki kurt sürüleri üzerine yapılan uzun süreli gözlemlere göre tipik bir kurt sürüsü en doğru nasıl tanımlanır?', 'Bir çift ve yavrularından oluşan bir aile', ['Liderlik için sürekli dövüşen akrabasız yetişkinler', 'Yalnızca erkeklerden oluşan bir av birliği', 'Her yıl dağılıp yeniden kurulan rastgele bir grup'], 'Esaret altındaki gözlemlerden doğan \'alfa kurt\' anlatısının aksine, doğadaki sürülerin çoğu üreyen bir çift ve onların yavrularından oluşan ailelerdir.'),
  ('Memelilerin yalnızca küçük bir bölümünde tek eşlilik görülür. Kuşlara göre memelilerde tek eşliliğin daha nadir olmasının olası açıklaması nedir?', 'Emzirmeyi yalnız dişinin yapabilmesi', ['Memelilerin yuva yapmaması', 'Memeli erkeklerinin yavruları tanıyamaması', 'Memelilerin hep tek başına yaşaması'], 'Memelilerde yavruyu süt ile yalnızca dişi besleyebildiği için erkeğin bakım katkısı çoğu türde sınırlıdır; kuşlarda ise iki ebeveyn de yavruya eşit biçimde besin taşıyabilir.'),
  ('Sürikat gruplarında baskın çiftin yavrularına, üremeyen diğer grup üyelerinin bakması ve onları beslemesi hangi davranışa örnektir?', 'İş birliğiyle yavru yetiştirme', ['Yavru parazitliği', 'Bölge savunması', 'Eşeysel seçilim'], 'İş birliğiyle yetiştirmede üremeyen yardımcılar çoğu zaman baskın çiftin akrabasıdır; yavrulara bakarak kendi genlerini dolaylı yoldan aktarmış olurlar.'),
  ('Fillerin hızlı ilerlerken bile dört ayağının aynı anda yerden kesilmemesinin nedeni nedir?', 'Kütlelerinin uçuş evresine izin vermemesi', ['Ayaklarının yere yapışkan bir salgıyla tutunması', 'Hortumlarını beşinci bacak gibi kullanmaları', 'Kuyruklarını dengede yere sürtmeleri'], 'Filler saatte 20 kilometreyi aşan hızlarda ilerleyebilir ama bu sırada her an en az bir ayakları yere değer; dev kütleleri havada uçuş evresine izin vermez.'),
  ('Güneydoğu Asya\'da yaşayan ve \'uçan lemur\' da denen kaguanlar (colugo) hangi özellikleriyle bilinir?', 'Geniş deri zarıyla süzülmeleri', ['Gerçek kanat çırparak uçmaları', 'Kuşlar gibi tüy taşımaları', 'Lemurlarla aynı takımda yer almaları'], 'Kaguanlar kendi takımlarını (Dermoptera) oluşturur; boyun, parmaklar ve kuyruk dahil vücudu çevreleyen deri zarıyla yüz metreyi aşan süzülüşler yapabilirler.'),
  ('Kuzey Amerika\'daki çatal boynuzlu antilobun uzun mesafede yüksek hızını koruyabilmesine katkı sağlayan özellik hangisidir?', 'Büyük kalbi ve akciğerleri', ['Kısa ve kalın kemikli bacakları', 'Ayak parmakları arasındaki perdeler', 'Kış uykusunda biriktirdiği yağ'], 'Çatal boynuzlu antilobun büyük kalbi, geniş soluk borusu ve güçlü akciğerleri dakikalar boyunca yüksek hızda koşmaya yetecek oksijeni sağlar.'),
  ('Panama Kıstağı oluştuktan sonra Güney Amerika\'dan Kuzey Amerika\'ya yayılan ve bugün ABD\'nin güneyinde yaşayan memelilerden biri hangisidir?', 'Dokuz bantlı armadillo', ['Kızıl geyik', 'Kahverengi ayı', 'Kanada vaşağı'], 'Dokuz bantlı armadillo Güney Amerika kökenlidir; Büyük Amerika Değişimi\'nden sonra kuzeye yayılmış ve günümüzde de ABD içinde yayılmayı sürdürmüştür.'),
  ('Atgiller evriminin büyük kısmını Kuzey Amerika\'da geçirmiştir. Avrupalılar geldiğinde Amerika\'da yabani at bulunmamasının nedeni nedir?', 'Atların orada tükenmiş olması', ['Atların Amerika\'ya hiç ulaşamamış olması', 'Yerli halkların atları Asya\'ya götürmesi', 'Atların kıtada yalnızca dağlarda saklanması'], 'Atlar Kuzey Amerika\'da evrimleşip Bering kara köprüsüyle Asya\'ya geçmiş, ancak yaklaşık 10.000 yıl önce Amerika\'da yok olmuştur; kıtaya 16. yüzyılda Avrupalılarca yeniden getirilmişlerdir.'),
  ('Kuzey Amerika ve Avrasya\'nın memeli faunalarının birbirine çok benzemesinin (ör. kurt, bozayı, sığın) en önemli nedeni nedir?', 'Bering kara köprüsü', ['İki kıtanın aynı enlemde olmaması', 'Okyanus akıntılarıyla hayvanların taşınması', 'İnsanların bu türleri birlikte götürmesi'], 'Deniz seviyesi düştüğünde Sibirya ile Alaska arasında oluşan kara köprüsü, birçok memelinin iki kıta arasında gidip gelmesine izin vermiştir.'),
  ('Memeliler en çok hangi kıtada endemik (başka yerde bulunmayan) takımlar ve aileler barındırır?', 'Avustralya', ['Avrupa', 'Kuzey Amerika', 'Antarktika'], 'Avustralya uzun süreli yalıtımı nedeniyle monotremler ve keselilerin pek çok endemik ailesini barındırır; Avrupa ve Kuzey Amerika ise kara bağlantıları nedeniyle daha az endemik takım içerir.'),
  ('Afrika\'da bugün hâlâ çok sayıda iri memeli türü yaşarken diğer kıtalarda buzul çağı sonunda iri memelilerin çoğunun yok olmasını açıklamaya çalışan görüşlerden biri hangisidir?', 'Afrika hayvanlarının insanla birlikte evrimleşmiş olması', ['Afrika\'da hiç buzul olmaması nedeniyle insan bulunmaması', 'Afrika memelilerinin derilerinin zehirli maddeler taşıması', 'Diğer kıtalarda yeterli ot yetişmemesi'], 'Bir görüşe göre Afrika ve kısmen Asya\'daki hayvanlar insan atalarıyla birlikte evrimleşip avcılara uyum sağlamış; insanın sonradan ulaştığı kıtalardaki hayvanlar ise bu deneyime sahip değildi. İklim değişikliğinin de payı tartışılmaktadır.'),
  ('Erkek fillerin ergenlikte doğdukları aile grubundan ayrıldıktan sonra yaşam biçimi genellikle nasıldır?', 'Tek başına ya da gevşek erkek gruplarında dolaşırlar', ['Hemen yeni bir aile grubunun lideri olurlar', 'Ömür boyu annelerinin yanına geri dönmezler ve hiç üreyemezler', 'Başka türlerin sürülerine katılırlar'], 'Genç erkek filler aile grubundan ayrıldıktan sonra yalnız ya da bekâr erkek gruplarında yaşar; dişi gruplarına yalnızca çiftleşme için kısa süre katılırlar.'),
  ('Anadolu\'nun ormanlık alanlarında doğal olarak yaşayan, Avrupa\'nın kızıl sincabından farklı olarak kulaklarında püskül bulunmayan sincap türü hangisidir?', 'Kafkas sincabı', ['Gri sincap', 'Uçan sincap', 'Yer sincabı'], 'Kafkas sincabı (Sciurus anomalus) Anadolu, Kafkasya ve Orta Doğu\'da yaşar; kızıl sincaptan farklı olarak kışın da kulak püskülü oluşturmaz ve karın bölgesi pas rengidir.'),
  ('Doğu Karadeniz\'in, örneğin Kaçkar Dağları\'nın sarp kayalıklarında yaşayan ve kısa, uçları geriye kıvrık boynuzlarıyla tanınan dağ keçisi hangisidir?', 'Çengel boynuzlu dağ keçisi', ['Yaban keçisi', 'Ankara keçisi', 'Muflon'], 'Çengel boynuzlu dağ keçisi (Rupicapra rupicapra) yüksek dağların kayalık yamaçlarında yaşar; her iki eşeyde de kısa, ucu kanca gibi geriye kıvrık boynuzlar bulunur.'),
  ('Bir köylü, aracının motor kablolarının geceleri kemirildiğini ve çatı arasında hareket sesleri duyduğunu söylüyor. Göğsünde beyaz, çatallı bir leke bulunan ince uzun bir hayvan gördüğünü belirtiyor. Bu hayvan büyük olasılıkla hangisidir?', 'Kaya sansarı', ['Ağaç sansarı', 'Avrupa porsuğu', 'Gelincik'], 'Kaya sansarı insan yerleşimlerine yakın yaşar, çatı aralarını kullanır ve araç kablolarını kemirmesiyle bilinir; beyaz ve çatallı göğüs lekesi onu sarımsı göğüs lekeli ağaç sansarından ayırır.'),
  ('Anadolu\'da görülen bir yabani kedinin vaşak olduğunu doğrulamak için hangi özellik bir arada aranmalıdır?', 'Kısa kuyruk ve kulak püskülleri', ['Uzun halkalı kuyruk ve beneksiz kürk', 'Siyah-beyaz çizgili gövde ve sivri kulaklar', 'Kuyruğun ucunda püskül ve yelesi'], 'Vaşak kısa, ucu siyah kuyruğu, kulak uçlarındaki siyah püsküller ve yüzünün iki yanındaki uzun yanak kıllarıyla diğer kedilerden ayrılır.'),
  ('Türkiye\'de görülen memeli türlerinin bir kısmının Avrupa, bir kısmının Orta Asya, bir kısmının ise Afrika ve Arabistan kökenli olması nasıl açıklanır?', 'Anadolu\'nun kıtalar arası bir köprü olması', ['Türkiye\'nin tamamen bir ada olması', 'Bütün türlerin insanlarca getirilmiş olması', 'Türkiye\'de tek tip iklim bulunması'], 'Anadolu, Avrupa-Sibirya, İran-Turan ve Akdeniz-Afrika etkilerinin buluştuğu bir köprüdür; karaca gibi Avrupa türleri ile çizgili sırtlan ve karakal gibi güneyli türler burada bir arada görülebilir.'),
  ('Konya\'nın Bozdağ çevresinde yaşayan ve erkeklerinde kalın, geriye kıvrık boynuzlar bulunan yabani koyun hangisidir?', 'Anadolu yaban koyunu', ['Çengel boynuzlu dağ keçisi', 'Argali', 'Merinos'], 'Anadolu yaban koyunu (Ovis gmelinii anatolica) Konya çevresinde yaşayan bir alt türdür; doğal dağılışı çok sınırlı olduğu için uzun süredir özel koruma altındadır.'),
  ('Koyun ve keçinin ilk evcilleştirildiği bölge ve zaman için en doğru seçenek hangisidir?', 'Bereketli Hilal, 10-11 bin yıl önce', ['Orta Avrupa, yaklaşık 2.000 yıl önce', 'Güney Amerika, yaklaşık 500 yıl önce', 'Avustralya, yaklaşık 40.000 yıl önce'], 'Arkeolojik ve genetik veriler, koyun ve keçinin Güneydoğu Anadolu, Zagros ve çevresini kapsayan Bereketli Hilal\'de Neolitik dönemin başında evcilleştirildiğini gösterir.'),
  ('Evcil hayvanlarda yabani atalarına göre beyin hacminin küçülmesi, sarkık kulak ve benekli renk gibi özelliklerin sık görülmesine ne ad verilir?', 'Evcilleştirme sendromu', ['Ada cüceleşmesi', 'Yakınsak evrim süreci', 'Kurucu etkisi ve darboğaz'], 'Evcilleştirme sendromu, uysallık için yapılan seçilimle birlikte farklı evcil türlerde ortaya çıkan ortak özellikleri anlatır; Rus tilki deneyinde de benzer değişimler gözlenmiştir.'),
  ('Evcil sığır ırklarının çoğunda boynuz bulunmasına karşın bazı ırklar doğal olarak boynuzsuzdur. Yetiştiriciler bu özelliği hangi yolla yaygınlaştırmıştır?', 'Boynuzsuz hayvanları seçerek', ['Buzağılara boynuz kesen ilaç vererek', 'Sığırları soğuk ahırlarda tutarak', 'Sığırlara az kalsiyumlu yem vererek'], 'Boynuzsuzluk kalıtsal bir özelliktir ve baskın bir genle ilişkilidir; yetiştiriciler bu özelliği taşıyan bireyleri seçerek boynuzsuz sürüler oluşturmuştur.'),
  ('Avrupa tavşanının evcilleştirilmesi koyun, keçi ve köpeğe göre ne zaman ve nerede gerçekleşmiştir?', 'Çok daha geç, Orta Çağ\'da Batı Avrupa\'da', ['Çok daha erken, Buzul Çağı\'nda Sibirya\'da', 'Aynı dönemde, Bereketli Hilal\'de', 'Antik Mısır\'da piramitlerden önce'], 'Tavşanın evcilleştirilmesi büyük ölçüde Orta Çağ\'da Fransa ve İspanya çevresinde gerçekleşmiştir; bu, Neolitik çağda evcilleştirilen koyun ve keçiden binlerce yıl sonradır.'),
  ('Güney Amerika\'da yaşamış, küçük bir otomobil boyutunda, kubbe biçimli tek parça zırh taşıyan gliptodonların yaşayan en yakın akrabaları hangileridir?', 'Armadillolar', ['Kaplumbağalar', 'Pangolinler', 'Kirpiler'], 'Gliptodonlar armadillolarla birlikte zayıf dişliler (Xenarthra) grubundadır; zırhları kaynaşmış kemik plakalardan oluşuyordu.'),
  ('Mamut ile mastodon fosillerini azı dişlerinden ayırt etmeye çalışan bir paleontolog hangi farka bakar?', 'Mamutta sırtlı, mastodonda konili azı', ['Mamutların ağzında hiç azı dişi bulunmaz', 'Mastodonun azısı keskin bir bıçak gibidir', 'İkisinin azı dişleri birbirinin tıpatıp aynısıdır'], 'Mamutların sırtlı, rende gibi azıları otlamaya; mastodonların koni çıkıntılı azıları ise yaprak, dal ve sürgün çiğnemeye uygundu.'),
  ('Buzul çağında Avrasya\'da yaşamış, boynuz açıklığı üç buçuk metreyi bulan ve \'İrlanda geyiği\' olarak da bilinen dev geyik hangisidir?', 'Megaloceros', ['Sığın', 'Ren geyiği', 'Kızıl geyik'], 'Megaloceros giganteus bilinen en büyük boynuzlara sahip geyiktir; adı İrlanda turbalıklarında çok sayıda iskelet bulunmasından gelir ama Avrasya\'nın geniş bir bölümünde yaşamıştır.'),
  ('Fransa\'daki Chauvet ve İspanya\'daki Altamira gibi mağaraların duvar resimleri, buzul çağı memelileri hakkında bilim insanlarına ne sağlar?', 'Dış görünüşlerine dair bilgi', ['Bu hayvanların DNA dizilerini', 'Bu hayvanların kesin ağırlıklarını', 'Bu hayvanların ses kayıtlarını'], 'Mağara resimleri yünlü gergedan, mamut ve mağara aslanı gibi hayvanların kürk rengi, yelesi ve vücut biçimi gibi fosillerde korunmayan özelliklerini gösterir.'),
  ('Tamamen sucul bir erken balina olan Basilosaurus\'un adı \'kral kertenkele\' anlamına gelir. Bu adın verilmesinin nedeni nedir?', 'Önce sürüngen sanılması', ['Kertenkeleler gibi pullu bir derisi olması', 'Karada kertenkeleler gibi güneşlenmesi', 'Yumurtalarını kıyıya bırakması'], 'Basilosaurus 19. yüzyılda ilk tanımlandığında dev bir deniz sürüngeni sanılmış; daha sonra dişleri incelenince memeli olduğu anlaşılmıştır.'),
  ('Erken balina fosillerinde bulunan çift makaralı aşık kemiği (astragalus) balinaların hangi grupla akraba olduğunu gösterir?', 'Çift toynaklılar', ['Etçiller', 'Kemirgenler', 'Tek toynaklılar'], 'Çift makaralı aşık kemiği çift toynaklılara özgüdür; erken balinalarda bu kemiğin bulunması, moleküler verilerle birlikte balinaların su aygırı gibi çift toynaklılarla akraba olduğunu doğrular.'),
  ('Avustralya\'da yaşamış \'keseli aslan\' Thylacoleo\'nun hangi akrabalarıyla aynı soydan geldiği kabul edilir?', 'Vombat ve koalalar', ['Afrika ve Asya aslanları', 'Tazmanya canavarı', 'Kanguru fareleri'], 'Thylacoleo bir etçil olmasına karşın otçul vombat ve koalaların bulunduğu keseli soyundan evrimleşmiştir; kedilere benzerliği yakınsak evrimdir.'),
  ('Güney Amerika\'da yaşamış keseli Thylacosmilus ile Kuzey Amerika\'daki Smilodon\'un ikisinde de uzun kılıç dişleri bulunması neyi gösterir?', 'Yakınsak evrimi', ['İkisinin aynı türden olduğunu', 'Ortak bir kılıç dişli atadan geldiklerini', 'Bu dişlerin yalnızca süs olduğunu'], 'Thylacosmilus keseli, Smilodon ise kedigildir; kılıç dişlerin iki soyda ayrı ayrı ortaya çıkması yakınsak evrimin çarpıcı bir örneğidir.'),
  ('Tenrekler ve altın köstebekler eskiden kirpi ve köstebeklerle aynı takımda sınıflandırılıyordu. Bu sınıflandırmanın değiştirilmesinin nedeni nedir?', 'DNA\'nın Afrika kökenli soyu göstermesi', ['Kirpi ve köstebeklerden daha büyük oldukları için', 'Kış uykusuna yatmadıklarının anlaşılması nedeniyle', 'Dikenleri ve kürek ayakları olmadığı için'], 'Görünüş benzerliği benzer yaşam biçiminden kaynaklanır; moleküler veriler tenrek ve altın köstebekleri fillerle aynı büyük grupta, Afrotheria\'da toplar.'),
  ('Güney Amerika\'nın And Dağları ormanlarında yaşayan ve dünyanın en küçük geyiği olarak bilinen tür hangisidir?', 'Pudu', ['Muntjak', 'Karaca', 'Misk geyiği'], 'Pudular omuz yüksekliği 30-40 santimetre kadar olan küçük geyiklerdir; erkeklerinde kısa, sivri boynuzlar bulunur.'),
  ('Afrika\'da yaşayan yeleli sıçanın zehirli bir ağacın kabuğunu çiğneyip tükürüğünü kürkündeki özel kıllara sürmesinin işlevi nedir?', 'Isıran avcıyı zehirlemek', ['Kürkünü su geçirmez yapmak', 'Yavrularını beslemek', 'Bölgesini kokuyla işaretlemek'], 'Yeleli sıçan zehirli Acokanthera kabuğundaki maddeleri emici özel kıllarına sürer; onu ısıran köpek gibi avcılar zehirlenebilir. Bu, memelilerde nadir görülen bir savunmadır.'),
  ('Afrika dikenli farelerinin avcının pençesinden kurtulmak için derilerinin kolayca yırtılması ve yaranın iz bırakmadan kapanması hangi yeteneklerine işaret eder?', 'Doku yenileme', ['Kış uykusu', 'Ekolokasyon', 'Renk değiştirme'], 'Afrika dikenli fareleri yırtılan derilerini, kıl köklerini ve hatta kulak dokusunu iz bırakmadan yenileyebilir; bu yetenek memelilerde olağan dışıdır ve yara iyileşmesi araştırmalarında incelenir.'),
  ('Ayna testinde kendini tanıdığına dair işaretler gösterdiği bildirilen hayvanlardan biri hangisidir?', 'Asya fili', ['Ev kedisi', 'Laboratuvar faresi', 'Evcil koyun'], '2006\'da Bronx Hayvanat Bahçesi\'ndeki Asya fili Happy\'nin alnındaki işareti aynada fark edip hortumuyla dokunduğu gözlenmiştir; büyük insansılar ve yunuslar da testi geçen türler arasındadır.'),
  ('Köpeklerin bir insanın elleriyle işaret ettiği kabı bulmada şempanzelerden bile başarılı olabildiği bulunmuştur. Bu yetenek en çok neyle açıklanır?', 'İnsanla birlikte evrimleşmeleri ve evcilleşme', ['Köpeklerin şempanzelerden daha büyük beyni olması', 'Köpeklerin renkleri daha iyi görmesi', 'Köpeklerin konuşmayı anlaması'], 'Binlerce yıllık evcilleşme süreci, köpeklerde insanın jest ve bakışlarını yorumlama yeteneğini güçlendirmiştir; yavru köpekler de bu beceriyi erken yaşta gösterir.'),
  ('Primatlarda beyin kabuğunun (neokorteks) beyne oranı ile türün tipik grup büyüklüğü arasında olumlu bir ilişki bulunmuştur. Bu bulgu hangi görüşü destekler?', 'Sosyal yaşamın beyni büyüttüğü', ['Büyük grupların beyni küçülttüğü', 'Beyin büyüklüğünün yalnızca vücut ısısına bağlı olduğu', 'Grup büyüklüğünün yalnızca yağışa bağlı olduğu'], 'Sosyal beyin hipotezine göre çok sayıda bireyle ilişkiyi izlemek bilişsel yük getirir; bu nedenle daha büyük gruplarda yaşayan primatların neokorteksi daha büyüktür.'),
  ('Bir köpeğin, adları söylendiğinde yüzlerce farklı oyuncağı birbirinden ayırt edip getirebildiğinin gösterildiği çalışmalar en çok hangi yeteneğe dikkat çekmiştir?', 'Sözcük-nesne ilişkisini öğrenme', ['Renkleri ayırt etme', 'Ekolokasyonla nesne bulma', 'Koku izini uzun süre takip etme'], 'Chaser adlı Border Collie\'nin bin dolayında oyuncağı adlarıyla tanıyabildiği bildirilmiştir; bu, bazı köpeklerin adları nesnelerle eşleştirmede olağanüstü başarılı olabileceğini gösterir.'),
  ('Kutup ayısı ile kodiak bozayısı en büyük karasal etçil unvanını paylaşır. Kutup ayısının ayağındaki hangi özellik buz üzerinde yürümeye uyumludur?', 'Tabandaki çıkıntılar ve kıllar', ['Perdeli ve kılsız tabanlar', 'Toynak benzeri sert kılıflar', 'Yapışkan bez salgıları'], 'Kutup ayısının iri patilerinin tabanları küçük papillalar ve kıllarla kaplıdır; bunlar buz üzerinde kaymayı azaltır ve soğuğa karşı yalıtım sağlar.'),
  ('Kar örtüsünün iklim değişikliğiyle daha geç oluşup daha erken eridiği bölgelerde kar tavşanları için hangi sorun ortaya çıkar?', 'Karsız zeminde göze çarpmaları', ['Kürklerinin hiç beyazlamaması', 'Kulaklarının küçülmesi', 'Kış uykusuna yatamamaları'], 'Kürk rengi değişimi gün uzunluğuna bağlı olduğundan kar takvimi değiştiğinde beyaz tavşan kahverengi toprakta kalır ve avcılarca kolay fark edilir.'),
  ('Bazı sincaplar besinlerini tek bir yerde toplamak yerine çok sayıda küçük çukura ayrı ayrı gömer. Bu dağınık depolamanın yararı nedir?', 'Stokun tümüyle çalınmasını önlemek', ['Besinlerin daha hızlı olgunlaşıp yumuşamasını sağlamak', 'Daha az sayıda yeri hatırlamayı gerektirmek', 'Besinleri yağmur ve dondan tamamen korumak'], 'Dağınık depolamada her çukur küçük bir pay içerir; başka bir hayvan birkaç zulayı bulsa bile depolanan besinin çoğu korunur. Bunun bedeli, pek çok yeri hatırlama zorunluluğudur.'),
  ('Kuzey Kutbu tilkilerinin çoğu kışın beyazlaşırken kıyı bölgelerinde yaşayan bazı popülasyonlar yıl boyunca koyu gri-kahverengi kalır. Bu \'mavi\' renk biçiminin kıyıda yaygın olması nasıl açıklanır?', 'Kıyıların kışın da çoğunlukla karsız olması', ['Kıyıdaki tilkilerin balık yemesiyle tüylerinin boyanması', 'Mavi biçimdeki tilkilerin daha yaşlı bireyler olması', 'Kıyıda gün uzunluğunun yıl boyu hiç değişmemesi'], 'Kar örtüsünün sürekli olmadığı kıyı kayalıklarında koyu kürk daha iyi gizleme sağlar; bu nedenle doğal seçilim kıyı popülasyonlarında mavi biçimi kayırır.'),
  ('Avrupa\'da yaşayan Nathusius cüce yarasası gibi bazı küçük yarasaların sonbaharda yaptığı yolculuk hakkında hangisi doğrudur?', 'Binlerce kilometrelik mevsimsel göçler yapabilirler', ['Hiç uçmadan kış boyunca yürürler', 'Yalnızca bir mağaradan diğerine birkaç metre giderler', 'Kuşların sırtında taşınırlar'], 'Halka takılarak izlenen Nathusius cüce yarasalarının Baltık bölgesinden Güney ve Batı Avrupa\'ya 2000 kilometreyi aşan göçler yaptığı belirlenmiştir.'),
  ('Çitaların avlarını yakaladıktan sonra genellikle hızla yemeye başlaması ve çevreyi sürekli kollaması en çok neyle açıklanır?', 'Avını kaptırma riskiyle', ['Sindirim sisteminin çok kısa olmasıyla', 'Etin çabuk donmasıyla', 'Avın yeniden canlanabilmesiyle'], 'Çitalar aslan ve sırtlan karşısında avlarını savunamaz; bu nedenle beslenmeyi hızlı tamamlar ve tetikte kalırlar.'),
  ('Ceylan sürüleri büyüdükçe her bireyin başını kaldırıp çevreyi kollamaya ayırdığı süre azalır ama sürü avcıyı yine erken fark eder. Bunun nedeni nedir?', 'Toplam gözetimin yüksek kalması', ['Büyük sürülerde avcıların hiç saldırmaması', 'Ceylanların büyük sürüde daha iyi görmesi', 'Sürünün liderinin bütün gözetimi üstlenmesi'], 'Kalabalık grupta her birey biraz göz kulak olsa bile toplam gözetim yeterlidir; böylece bireyler beslenmeye daha çok zaman ayırabilir.'),
  ('Kuzey Amerika\'da bir çakal ile bir porsuğun birlikte yer sincabı avladığı gözlenmiştir. Bu iş birliğinin işleyişi en iyi nasıl açıklanır?', 'Biri kazar, diğeri kaçanı yakalar', ['Çakal sincapları porsuğa getirip paylaşır', 'Porsuk çakalın sırtında taşınır', 'İkisi de sincapları ortak bir yuvada saklar'], 'Porsuk tünele kazarak girdiğinde yer sincapları başka çıkışlardan kaçar ve çakal onları yakalar; çakal yüzeydeyken de sincaplar yer altında kalıp porsuğa yakalanır. Böylece iki avcı da yarar sağlar.'),
  ('Avustralya\'nın Rottnest Adası\'nda yaşayan ve insanlardan pek kaçmamasıyla tanınan küçük keseli hangisidir?', 'Kuoka', ['Numbat', 'Koala', 'Vombat'], 'Kuoka küçük bir kanguru akrabasıdır; tilki gibi dışarıdan getirilmiş avcıların bulunmadığı adalarda çok sayıda yaşar.'),
  ('Koalaların parmak uçlarındaki izlerle ilgili ilginç olan özellik hangisidir?', 'İnsanınkine çok benzemeleri', ['Hiç parmak izlerinin olmaması', 'Parmak izlerinin her yıl değişmesi', 'Parmak izlerinin ışık saçması'], 'Koala parmak izleri sarmal ve ilmek desenleriyle insanınkilere o kadar benzer ki mikroskopla bile ayırt etmek zordur; bu, ağaç dallarını kavrama ile ilişkili yakınsak bir özelliktir.'),
  ('Kangurular ile valabiler arasındaki fark için en doğru ifade hangisidir?', 'Ayrım çoğunlukla boyuta dayanır', ['Valabiler keseli değildir', 'Kangurular yalnız Yeni Zelanda\'da yaşar', 'Valabiler yumurta bırakır'], 'Kanguru ve valabi aynı familyadandır; genellikle iri türlere kanguru, daha küçük türlere valabi denir. Bu ayrım bilimsel değil gündelik bir adlandırmadır.'),
  ('Yeni doğan dev panda yavrusu annesine göre nasıldır?', 'Annesinin binde biri kadardır', ['Annesinin yarısı kadardır ve hemen yürür', 'Siyah-beyaz kürkle ve açık gözlerle doğar', 'Yumurtadan çıkar ve kesede büyür'], 'Dev panda yavrusu yaklaşık 100 gram doğar; annesine oranla plasentalı memeliler arasında en küçük yeni doğanlardandır. Siyah-beyaz deseni birkaç haftada belirginleşir.'),
  ('Serengeti\'deki araştırmalara göre erkek aslanların yelesinin daha koyu ve uzun olması neyi yansıtır?', 'Erkeğin sağlığını ve gücünü', ['Erkeğin yaşının çok genç olduğunu', 'Erkeğin aç olduğunu', 'Erkeğin sürüden kovulduğunu'], 'Koyu yele testosteron ve iyi beslenmeyle ilişkilidir; dişiler koyu yeleli erkekleri tercih eder, rakip erkekler de onlardan çekinir. Buna karşın koyu yele sıcakta daha fazla ısınmaya yol açar.'),
  ('Afrika dışındaki son yabani aslan popülasyonu hangi bölgede yaşar?', 'Hindistan\'daki Gir Ormanı ve çevresi', ['Anadolu\'daki Toros Dağları ve çevresi', 'İran\'daki Zagros Dağları ve vadileri', 'Arabistan çöllerinin vaha kuşağı'], 'Asya aslanı bir zamanlar Anadolu\'dan Hindistan\'a kadar yaşardı; bugün yalnızca Hindistan\'ın Gujarat eyaletindeki Gir Ormanı ve çevresinde bulunur.'),
  ('Orta ve Güney Amerika ormanlarında yaşayan margay, arka ayak bileklerini olağan dışı biçimde döndürebilir. Bu yetenek ona ne sağlar?', 'Ağaçtan baş aşağı inmeyi', ['Suda perdeli ayakla yüzmeyi', 'Toprağı hızla kazmayı', 'Kanat gibi süzülmeyi'], 'Margayın arka bileği yaklaşık 180 derece dönebilir; böylece sincaplar gibi ağaçtan baş aşağı inebilir ve tek ayağıyla dala asılabilir.'),
  ('Güney Amerika otlaklarında yaşayan yeleli kurdun uzun bacaklarının en akla yatkın işlevi hangisidir?', 'Uzun otların üstünden görmek', ['Derin karda batmadan yürümek', 'Sığ suda balık avlamak', 'Ağaçlara kolayca tırmanmak'], 'Yeleli kurt uzun otların bulunduğu savan benzeri alanlarda yaşar; uzun bacakları ona otların üstünden bakma olanağı verir. Beslenmesinin önemli kısmını da \'kurt elması\' denen bir meyve oluşturur.'),
  ('Batı Afrika\'daki bazı şempanze topluluklarında erkeklerin iş birliğiyle avladığı primat hangisidir?', 'Kızıl kolobus maymunu', ['Dağ gorili', 'Bonobo', 'Mandril'], 'Şempanzeler çoğunlukla meyve yer ama Tai ve Gombe gibi bölgelerde kızıl kolobus maymunlarını grup hâlinde avladıkları gözlenmiştir; elde edilen et grup içinde paylaşılır.'),
  ('Tazmanya canavarı yavrularının pirinç tanesi büyüklüğünde doğması ve annenin dört meme başının bulunması hangi sonucu doğurur?', 'En çok dört yavru yaşayabilir', ['Bütün yavruların ikişer ikişer emzirilmesi', 'Yavruların kendi besinlerini bulması', 'Annenin yavruları yumurtaya dönüştürmesi'], 'Tazmanya canavarı çok sayıda yavru doğurabilir ama yalnız dört meme başı vardır; memeye ilk tutunan dört yavru kesede gelişimini sürdürür.'),
  ('Avustralya\'da yaşayan şeker planörlerinin ve diğer küçük keselilerin kışın enerji tasarrufu için başvurduğu yöntem hangisidir?', 'Sokulup günlük torpora girmek', ['Güneye göç etmek', 'Kürklerini dökmek', 'Sürekli titreyerek ısınmak'], 'Küçük keseliler soğuk günlerde yuvada birbirine sokulur ve vücut ısılarını birkaç saatliğine düşürerek enerji tasarrufu yapar.'),
  ('Çöl memelilerinin böbreklerinde Henle kulpunun çok uzun olması onlara hangi yararı sağlar?', 'Yoğun idrarla su tasarrufu', ['Kanı daha hızlı pıhtılaştırmak', 'Kanı ısıtmak', 'Tuzu terle atmak'], 'Uzun Henle kulpu böbrek dokusunda güçlü bir tuz derişimi farkı oluşturur; bu sayede idrardan daha çok su geri emilir ve çok yoğun idrar üretilir.'),
  ('Memelilerde kaburgalar genellikle yalnızca göğüs bölgesindeki omurlara bağlıdır; bel bölgesinde kaburga bulunmaz. Bu düzen hangi yapının işleyişiyle uyumludur?', 'Diyaframlı soluk alma', ['Kalbin bel bölgesinde yer alması', 'Böbreklerin kaburgalarla korunması', 'Kuyruk ağırlığının bele aktarılması'], 'Kaburgasız bel bölgesi gövdenin esnemesine ve diyafram kasıldığında karın organlarının aşağı itilebilmesine olanak verir; bu, memelilerdeki etkili soluk alıp vermeyle ilişkilidir.'),
  ('İmpalaların iki bireyin sırayla birbirinin boynunu ve başını dişleriyle temizlemesi davranışı en iyi nasıl açıklanır?', 'Ulaşamadıkları yerleri temizlemek', ['Rakibini yaralamak', 'Kur yapmak için tuz yalamak', 'Sürü liderini belirlemek'], 'İmpalalar kendi ağızlarıyla ulaşamadıkları baş ve boyun bölgesini karşılıklı tımarla temizler; temizleme genellikle sırayla ve eşit sayıda yapılır, bu da karşılıklı yarara dayalı bir iş birliğidir.'),
  ('Bazı çiftçilerin koyun sürülerini korumak için sürünün yanına lama yerleştirmesi hangi davranışlarına dayanır?', 'Avcılara karşı saldırganlıkları', ['Sürüye süt vermeleri', 'Kurtlarla aynı dili konuşmaları', 'Geceleri sürüyü ağaçlara taşımaları'], 'Bekçi lamalar yabancı köpekgilleri görünce alarm verir, onlara doğru yürür, tekmeler ve tükürür; bu nedenle bazı çiftçiler onları koruyucu hayvan olarak kullanır.'),
  ('Erkek koalaların vücut boyutlarına göre şaşırtıcı derecede kalın ve derin böğürme sesleri çıkarabilmesini sağlayan yapı hangisidir?', 'Ek ses kıvrımları', ['Burunlarındaki hava keseleri', 'Göğüslerindeki kemik plaka', 'Yanaklarındaki kese'], 'Erkek koalaların yumuşak damakta, gırtlağın dışında yer alan büyük ek ses kıvrımları vardır; bu yapı, çok daha iri bir hayvandan beklenecek kadar pes sesler üretmelerini sağlar.'),
  ('Filler 14 Hz frekansında infrases üretebilir. Ses hızı 340 m/s ise bu sesin dalga boyu yaklaşık kaç metredir?', '24', ['4', '140', '2,4'], 'Dalga boyu = hız / frekans = 340 / 14 ≈ 24 metredir. Bu kadar uzun dalgalar engellerden az etkilenir ve kilometrelerce yol alabilir.'),
  ('Çitalar arasında bir bireyden alınan deri naklinin akraba olmayan başka bir çitada reddedilmediği bulunmuştur. Bu durum en iyi nasıl açıklanır?', 'Genetik çeşitliliğin çok düşük olması', ['Çitaların bağışıklık sisteminin hiç olmaması', 'Deri hücrelerinin çitalarda hiç bölünmemesi', 'Çitaların derisinde kan damarı bulunmaması'], 'Çitaların geçmişte yaşadığı ciddi popülasyon darboğazları genetik çeşitliliği azaltmıştır; bireyler doku uyumu genleri bakımından birbirine çok benzediği için nakil reddedilmez.'),
  ('Çin ve Kore\'de yaşayan, erkeklerinde boynuz yerine ağızdan sarkan uzun köpek dişleri bulunan geyik hangisidir?', 'Su geyiği', ['Ren geyiği', 'Pudu', 'Alageyik'], 'Su geyiğinin erkeklerinde boynuz yoktur; uzun üst köpek dişleri çiftleşme dönemindeki dövüşlerde kullanılır. Bu yüzden halk arasında \'vampir geyik\' diye de anılır.'),
  ('Güney Amerika\'daki örümcek maymunlarının ellerinde başparmağın çok küçük olması ya da hiç bulunmaması hangi hareket biçimiyle ilişkilidir?', 'Daldan dala sallanarak ilerleme', ['Yerde parmak eklemleri üzerinde yürüme', 'Toprağı kazma', 'Sudan balık yakalama'], 'Başparmağı küçülmüş eller, dala kanca gibi takılıp hızla sallanmaya uygundur; örümcek maymunları ayrıca güçlü kavrayıcı kuyruklarını beşinci bir kol gibi kullanır.'),
  ('Kuzey Amerika\'nın Kayalık Dağları\'nda yaşayan beyaz kürklü \'dağ keçisi\' (Oreamnos) hakkında hangisi doğrudur?', 'Keçi akrabasıdır ama gerçek keçi değildir', ['Gerçek bir yaban keçisi türüdür', 'Geyikgillerdendir', 'Koyunla keçi melezidir'], 'Oreamnos keçi ve koyunların bulunduğu alt familyadadır ama ayrı bir cinstir; evcil keçinin atası olan Capra türlerinden farklıdır.'),
  ('Moğolistan ve Çin bozkırlarında yaşayan Asya yaban eşeği (kulan) için hangisi doğrudur?', 'Evcil eşekten ayrı bir türdür', ['Evcil eşeğin doğrudan atasıdır', 'Ova zebrasının bir alt türüdür', 'Tek hörgüçlü devenin akrabasıdır'], 'Kulan ve diğer Asya yaban eşekleri ayrı bir türdür; evcil eşek ise Afrika yaban eşeğinden türemiştir.'),
  ('Afrika\'da dişi filler arasında yaşlı bir dişinin, kuraklık yıllarında grubun hayatta kalma şansını artırdığı gösterilmiştir. Bu durumun en olası açıklaması nedir?', 'Yaşlı dişinin su yerlerini bilmesi', ['Yaşlı dişinin daha çok süt vermesi', 'Yaşlı dişinin avcıları kokusuyla kaçırması', 'Yaşlı dişinin daha az su içmesi'], 'Onlarca yıllık deneyime sahip yaşlı dişiler, nadiren kullanılan su kaynaklarını ve uygun otlakları hatırlar; bu bilgi kurak dönemlerde grubun yaşamını kurtarabilir.'),
  ('Afrika fillerinde fildişsiz doğan dişilerin oranının bazı bölgelerde artması en çok hangi etkenle ilişkilendirilmiştir?', 'Fildişi avcılığının seçilim baskısı', ['İklimin soğuması', 'Fillerin daha az su içmesi', 'Fillerin yeni bir besine geçmesi'], 'Fildişi taşıyan filler kaçak avcılarca hedef alındığında fildişsiz bireyler daha çok hayatta kalıp ürer; Mozambik\'teki iç savaş döneminden sonra bu oranın belirgin biçimde arttığı gösterilmiştir.'),
  ('Kutup ayılarının ve bozayıların bazı bölgelerde çiftleşip verimli melez yavrular verebilmesi bu iki türün ilişkisi hakkında ne gösterir?', 'Yakın zamanda ayrıldıklarını', ['Aynı tür olduklarını kesin olarak', 'Melezlerin her zaman kısır olduğunu', 'Kutup ayısının bozayının atası olduğunu'], 'Kutup ayısı ve bozayı birkaç yüz bin yıl önce ayrılmış yakın türlerdir; bu yüzden üreme engelleri tam gelişmemiştir. Biyolojik tür kavramının sınırlarını gösteren bir örnektir.'),
  ('Bir doğa belgeselinde bir hayvanın uzun, sivri, hareketli burnuyla toprağı eşeleyerek böcek aradığı, gövdesinin ise dikenli olduğu görülüyor. Hayvan Madagaskar\'da çekildiğine göre büyük olasılıkla hangisidir?', 'Tenrek', ['Avrupa kirpisi', 'Oklukirpi', 'Ekidne'], 'Madagaskar\'da gerçek kirpi bulunmaz; kirpiye benzeyen dikenli tenrekler aynı nişi doldurur. Ekidne ise Avustralya ve Yeni Gine\'de yaşar.'),
  ('Avrupa porsuklarının kış aylarında yuvalarında uzun süre uyuşuk kalması, ama gerçek kış uykusuna yatan hayvanlar kadar vücut ısısını düşürmemesi nasıl nitelenir?', 'Kış dinlenmesi', ['Estivasyon', 'Gecikmeli tutunma', 'Göç'], 'Porsuklar soğuk dönemlerde yuvada uzun süre kalıp metabolizmalarını bir miktar düşürür ama kolayca uyanabilir; bu durum derin kış uykusundan farklıdır.'),
  ('Kızıl tilki, kurt ve çakal gibi köpekgillerin birlikte yaşadığı bir bölgede kurtların çoğalmasının çakal ve tilki sayısını azaltması hangi ilişkiyle açıklanır?', 'Büyük avcının küçükleri baskılaması', ['Çakal ve tilkilerin kurtları avlaması', 'Üç türün aynı yavruları paylaşması', 'Kurtların tilkilere besin taşıması'], 'Büyük köpekgiller daha küçük rakiplerini öldürebilir ya da onları bölgeden uzaklaştırabilir; bu nedenle kurt sayısı arttığında çakal sayısı düşer, tilkiler ise bu durumdan yarar sağlayabilir.'),
  ('Atın ön bacağının arka yüzünde, toynağa giden büyük kemiğin iki yanında bulunan ince \'kızak kemikleri\' neyin kalıntısıdır?', 'Atasal yan parmakların', ['Kırılmış kemiklerin kaynamış parçalarının', 'Kuyruk omurlarının', 'Kaburgaların'], 'At soyunda parmak sayısı zamanla azalmış; ikinci ve dördüncü parmaklar bugünkü atta ortadaki kemiğin yanında ince kızak kemikleri olarak kalmıştır.'),
  ('Bir atın ön bacağının ortasında \'diz\' sanılan ve öne doğru bükülen eklem anatomik olarak insandaki hangi ekleme karşılık gelir?', 'Bileğe', ['Dize', 'Dirseğe', 'Omza'], 'Atlar parmak ucunda yürüdüğü için el bileği yerden yüksektedir; halk arasında \'ön diz\' denen eklem aslında bilek eklemidir.'),
  ('Kedi, köpek ve at gibi hızlı koşan memelilerde köprücük kemiğinin körelmiş olması ya da hiç bulunmaması hangi yararı sağlar?', 'Adımın uzayabilmesi', ['Göğüs kafesinin daha sert olması', 'Ön bacakların yana açılabilmesi', 'Daha kolay tırmanabilmek'], 'Köprücük kemiği kol ile gövdeyi sabitler; koşucu memelilerde bu bağlantının zayıflaması kürek kemiğinin bacakla birlikte ileri-geri kaymasına ve adımın uzamasına izin verir. Tırmanan primatlarda ise köprücük kemiği gelişmiştir.'),
  ('Fransa ve İtalya\'da toprak altındaki değerli yer mantarlarını (trüf) bulmak için geleneksel olarak dişi domuzların kullanılmasının nedeni nedir?', 'Trüfün feromon benzeri kokusu', ['Domuzların toprağı kazamaması', 'Domuzların trüfü hiç yememesi', 'Domuzların gözlerinin çok iyi görmesi'], 'Bazı trüf türleri erkek domuz feromonuna benzeyen bir bileşik içerir; bu nedenle dişi domuzlar trüfe güçlü bir ilgi gösterir. Domuzlar buldukları trüfü yiyebildiği için günümüzde çoğunlukla eğitilmiş köpekler tercih edilir.'),
  ('Bazı sivri fare türlerinin karanlıkta çevrelerini tanımak için yüksek frekanslı cıvıltılar çıkarıp yankılarını kullandığı bilinir. Bu durum ekolokasyon hakkında neyi gösterir?', 'Ekolokasyonun başka gruplarda da olduğunu', ['Sivri farelerin yarasalardan evrimleştiğini', 'Sivri farelerin uçabildiğini', 'Ekolokasyonun yalnızca suda işe yaradığını'], 'Ekolokasyon yarasa ve dişli balinaların yanı sıra bazı sivri fareler ve tenreklerde de basit bir biçimde görülür; benzer yetenek farklı soylarda bağımsız olarak gelişmiştir.'),
  ('Bir yarasa annesinin doğurduğu tek yavrunun ağırlığı annenin ağırlığının yaklaşık dörtte biri olabilir. Bu oranın insanla karşılaştırılması neyi gösterir?', 'Yarasaların görece çok büyük yavru doğurduğunu', ['Yarasa yavrularının çok küçük doğduğunu', 'Yarasaların yumurta bıraktığını', 'Yarasa annelerinin yavrularını hiç emzirmediğini'], 'İnsan bebeği annenin ağırlığının yaklaşık yüzde beşi kadardır; yarasalarda bu oranın yüzde yirmi beşe ulaşması, uçan bir anne için dikkat çekici ölçüde büyük bir yatırımdır.'),
  ('Kobayların gebeliği yaklaşık 68 gün sürer ve yavrular kürklü, gözleri açık doğar; sıçanlarda ise gebelik yaklaşık 21 gün sürer ve yavrular çıplak doğar. Bu karşılaştırmadan hangi genelleme çıkarılabilir?', 'Uzun gebelik, gelişmiş yavru demektir', ['Gebelik süresinin yavru gelişimiyle hiçbir ilişkisi yoktur', 'Kısa gebelik her zaman daha iri yavru demektir', 'Kemirgen yavruları her zaman gözleri açık doğar'], 'Benzer boyuttaki iki kemirgende gebeliğin uzaması yavrunun anne karnında daha uzun süre gelişmesi demektir; bu yüzden kobay yavruları doğduktan hemen sonra koşabilir.'),
  ('Kenya\'daki Elgon Dağı\'nda fillerin karanlık mağaralara girip duvarlardan kaya kazımasının nedeni nedir?', 'Tuz ve mineral almak', ['Mağarada yaşayan yarasaları avlamak', 'Serinlemek için mağara suyuna girmek', 'Dişlerini bileylemek'], 'Elgon Dağı filleri Kitum gibi mağaralarda fildişleriyle sodyumca zengin kayayı kazıyıp yer; bu davranış kuşaklar boyu öğrenilerek sürdürülür.'),
  ('Orta Afrika ormanlarında fillerin büyük meyveleri yiyip tohumlarını kilometrelerce uzağa dışkıyla bırakması orman için neden önemlidir?', 'Büyük tohumların başka yayıcısı azdır', ['Fillerin tohumları tamamen sindirip yok etmesi', 'Ağaçların fil dışkısında hiç çimlenememesi', 'Tohumların yalnızca rüzgârla yayılması'], 'Orman filleri bazı ağaç türlerinin büyük tohumlarını yayabilen sayılı hayvanlardandır; tohumlar dışkının içinde gübreyle birlikte uzaklara taşınır.'),
  ('Kuzey Amerika\'nın Pasifik kıyısında bozayıların yakaladıkları somonları ormana taşıyıp yarı yenmiş bırakması orman ekosistemini nasıl etkiler?', 'Denizden ormana besin taşır', ['Ormandaki bütün böcekleri öldürür', 'Ağaçların yaprak dökmesini engeller', 'Nehirlerin tuzlanmasına yol açar'], 'Ayıların bıraktığı somon kalıntıları çürüyerek toprağa azot ve fosfor katar; dere kenarındaki ağaçların dokularında deniz kökenli azot izlerine rastlanır.'),
  ('Keselilerin Güney Amerika\'dan Avustralya\'ya hangi yolla ulaştığı düşünülür?', 'Antarktika üzerinden karadan', ['Okyanusu yüzerek geçerek', 'Kuşlarca taşınarak', 'Kuzey Kutbu\'ndan buz üzerinde yürüyerek'], 'Gondvana kıtası parçalanmadan önce Güney Amerika, Antarktika ve Avustralya birbirine bağlıydı; Antarktika\'da bulunan keseli fosilleri bu göç yolunu destekler.'),
  ('Kuzey Amerika\'daki Virginia opossumunun birçok yılan türünün zehrine karşı dayanıklı olması onun beslenmesinde nasıl bir avantaj sağlar?', 'Zehirli yılanları da avlayabilmesi', ['Yalnızca bitkilerle beslenebilmesi', 'Kış uykusuna yatabilmesi', 'Avcılardan zehirli olduğu için kaçınılması'], 'Opossumun kanındaki bazı proteinler çıngıraklı yılan gibi türlerin zehrini etkisizleştirebilir; bu sayede yılanları da besin listesine katabilir.'),
  ('Avustralya\'da plasentalı yırtıcıların gelişmediği uzun bir dönemde etçil nişleri hangi hayvanlar doldurmuştur?', 'Keseli etçiller ve sürüngenler', ['Primatlar', 'Kedigiller', 'Ayılar'], 'Avustralya\'da tilasin, keseli aslan ve Tazmanya canavarı gibi keseli etçiller ile dev kertenkeleler ve timsahlar büyük yırtıcı rollerini üstlenmiştir.'),
  ('Dinozor çağının sonunda gerçekleşen kitlesel yok oluşu memelilerin önemli bir kısmının da atlattığı bilinir. Küçük memelilerin bu felaketten sağ çıkma şansını artırdığı düşünülen özellikler hangileridir?', 'Küçük boyut ve esnek beslenme', ['Büyük boyut ve tek tür besine bağımlılık', 'Yalnızca okyanus açıklarında yaşama', 'Soğukkanlı olma ve güneşlenme'], 'Çarpmanın ardından besin zincirleri çökerken az besinle yetinebilen, yer altında korunabilen ve böcek, tohum gibi çeşitli kaynakları kullanabilen küçük hayvanlar daha avantajlıydı.'),
  ('Memelilerde kulak kemikçiklerinin çene kemiklerinden evrimleştiğini destekleyen embriyolojik kanıt hangisidir?', 'Keseli yavrularındaki gelişim sırası', ['Kulak kemikçiklerinin erişkinde de çeneye kaynaşmış olması', 'Kemikçiklerin dişlerden çıkması', 'Kemikçiklerin kaburgalardan oluşması'], 'Keseli yavrularında çekiç ve örsün öncülleri doğumdan sonra bir süre alt çenenin arkasında çene eklemi gibi çalışır, sonra kafatasına göç ederek orta kulağa yerleşir.'),
  ('Afrika\'daki Karoo havzasının kayaçlarında çok sayıda \'memeli benzeri sürüngen\' fosili bulunmasının bilim için önemi nedir?', 'Memelilere geçişin izlenebilmesi', ['Dinozorların kökeninin burada bulunması', 'İnsan atalarının burada yaşaması', 'Kuşların ilk burada uçması'], 'Karoo\'daki Permiyen ve Triyas katmanları terapsit ve sinodontlar bakımından zengindir; bu fosiller çene, diş ve iskelet özelliklerinin memelilere doğru nasıl değiştiğini gösterir.'),
  ('\'Memeliler sürüngenlerden evrimleşmiştir\' cümlesi biyologlarca neden tam doğru kabul edilmez?', 'İki soy ortak bir atadan ayrılmıştır', ['Memeliler balıklardan doğrudan evrimleşmiştir', 'Sürüngenler memelilerden evrimleşmiştir', 'Memeliler ile sürüngenlerin hiçbir ortak atası yoktur'], 'Sinapsitler (memeli soyu) ve sauropsitler (sürüngen ve kuş soyu) yumurtası zarlı ortak bir amniyot atadan ayrılan iki koldur; bu nedenle memelilerin bugünkü sürüngenlerden türediği söylenemez.'),
  ('Kaliforniya yer sincaplarının çıngıraklı yılanlarla karşılaştığında kuyruklarını sallarken kuyruklarına daha çok kan pompalayıp ısıtmasının olası işlevi nedir?', 'Yılana ısıyla uyarı göstermek', ['Kuyruklarını yılana yem olarak sunmak', 'Yılanın zehrini kuyrukta etkisizleştirmek', 'Yuvadaki yavrularını ısıtmak'], 'Çıngıraklı yılanlar sıcaklığı algılayabildiğinden ısınmış kuyruk onlara belirgin bir sinyal olur; sincaplar bu uyarıyı ısı algılamayan yılan türlerine karşı kullanmaz.'),
  ('Yetişkin ev kedilerinin birbirleriyle iletişimde nadiren miyavlayıp insanlara karşı sık miyavlaması en iyi nasıl açıklanır?', 'İnsanla iletişimde pekişmiş olması', ['Kedilerin birbirini hiç duyamaması', 'Miyavlamanın yalnız avcılara karşı kullanılması', 'Kedilerin ses tellerinin yaşla kaybolması'], 'Yavru kediler annelerine miyavlar; erişkin kediler ise birbirleriyle daha çok koku ve beden diliyle iletişim kurar. İnsanlara yönelik miyavlama, karşılık gördükçe pekişen bir davranıştır.'),
  ('Şempanzelerde dudakların geriye çekilip dişlerin sıkıca birleşmiş biçimde gösterildiği yüz ifadesi genellikle neyi anlatır?', 'Korku ya da boyun eğme', ['Neşe ve oyun isteği', 'Saldırıya hazırlık', 'Açlık ve besin isteği'], 'Bu \'korku sırıtması\' alt sıradaki bir bireyin baskın bireye karşı gerginliğini ve boyun eğişini gösterir; insandaki gülümsemeyle evrimsel bir bağlantısı olabileceği öne sürülür.'),
  ('Kedi kumu ya da çiğ etle insanlara bulaşabilen Toxoplasma parazitinin eşeyli üremesini yalnızca hangi hayvanların bağırsağında tamamlayabildiği bilinir?', 'Kedigiller', ['Köpekgiller', 'Kemirgenler', 'Kuşlar'], 'Toxoplasma pek çok memeli ve kuşu ara konak olarak kullanır ama eşeyli üremesini yalnız kedigillerin bağırsağında yapar; bu nedenle kedi dışkısı yayılmada önemlidir.'),
  ('Toxoplasma ile enfekte olmuş farelerin kedi kokusundan kaçınma davranışını kaybedebildiği bildirilmiştir. Bu bulgu parazitin yaşam döngüsü açısından nasıl yorumlanır?', 'Parazitin kediye geçmesini kolaylaştırır', ['Farenin daha uzun yaşamasını sağlar', 'Parazitin fareden insana geçişini engeller', 'Kedilerin fare yemesini önler'], 'Kediden korkmayan fare daha kolay avlanır; böylece parazit eşeyli üreyebildiği kedinin bağırsağına ulaşır. Bu, parazitin konak davranışını değiştirmesine örnek gösterilir.'),
  ('Yalnız yaşayan bir memelinin bölgesindeki ağaçlara, kayalara ve patikalara düzenli olarak dışkı ve idrar bırakmasının avcı-av ilişkisi dışındaki temel işlevi nedir?', 'Kavgasız iletişim kurmak', ['Toprağı gübrelemek', 'Avları çekmek', 'Kendini serinletmek'], 'Koku işaretleri bölge sahibinin varlığını, cinsiyetini ve üreme durumunu uzun süre iletir; böylece bireyler karşılaşıp kavga etmeden birbirinden haberdar olur.'),
  ('Aşağıdaki memeli gruplarından hangisi Afrika\'ya özgüdür ve Güney Amerika\'da doğal olarak bulunmaz?', 'Zürafalar', ['Yarasalar', 'Kemirgenler', 'Kedigiller'], 'Zürafagiller yalnızca Afrika\'da doğal olarak yaşar; yarasalar, kemirgenler ve kedigiller ise Güney Amerika\'da da doğal olarak bulunur.'),
  ('Bir hayvanat bahçesinde aynı yaştaki iki kurttan biri yalnız, diğeri bir grupla büyütülmüştür. Grup içinde büyüyenin sosyal davranışları daha olağan gelişmiştir. Bu gözlem en iyi neyi destekler?', 'Öğrenmenin önemli olduğunu', ['Sosyal davranışın tamamen doğuştan olduğunu', 'Kurtların yalnız yaşamaya uyumlu olduğunu', 'Grupta büyümenin zekâyı azalttığını'], 'Sosyal memelilerde oyun, iletişim ve hiyerarşi davranışları büyük ölçüde gençlikte türdeşlerle etkileşim sırasında öğrenilir; yalnız büyüyen bireylerde bu davranışlar eksik kalabilir.'),
  ('Türkiye\'de doğal olarak yaşayan geyikgil türleri hangi seçenekte doğru verilmiştir?', 'Kızıl geyik, alageyik ve karaca', ['Ren geyiği, sığın ve karaca', 'Kızıl geyik, misk geyiği ve muntjak', 'Alageyik, pudu ve sığın'], 'Türkiye\'de kızıl geyik başta Karadeniz ve Trakya ormanlarında, karaca geniş bir alanda, alageyik ise çok sınırlı bir bölgede doğal olarak yaşar.'),
  ('Bursa\'da geliştirilen Karacabey merinosu koyununun yetiştirilmesinde öncelikli amaç neydi?', 'İnce ve kaliteli yün üretmek', ['Yalnızca süt verimini artırmak', 'Kuyruk yağını büyütmek', 'Koyunu yük hayvanı yapmak'], 'Merinos koyunları ince ve sık yün lifleriyle bilinir; Karacabey merinosu yerli koyunların merinosla melezlenmesiyle yün ve et verimi için geliştirilmiştir.'),
  ('Türkmenistan\'da yetiştirilen ve kıllarının metalik parlaklığıyla tanınan dayanıklı at ırkı hangisidir?', 'Ahal-Teke', ['Arap atı', 'Haflinger', 'Shetland midillisi'], 'Ahal-Teke çöl koşullarına dayanıklı, ince yapılı bir at ırkıdır; kıllarındaki ışığı yansıtan yapı ona altın ya da gümüş gibi parlak bir görünüm verir.'),
  ('Trakya ve Batı Anadolu\'da yetiştirilen, gri renkli, uzun boynuzlu ve kötü koşullara dayanıklı yerli sığır ırkı hangisidir?', 'Boz ırk', ['Holştayn', 'Jersey', 'Simental'], 'Boz ırk, Türkiye\'nin yerli sığır ırklarındandır; verimi düşük olsa da hastalık ve zor koşullara dayanıklılığı nedeniyle gen kaynağı olarak korunur. Holştayn, Jersey ve Simental yabancı kökenli ırklardır.'),
  ('Kültür ırkı süt ineklerinin yerli ırklara göre çok daha fazla süt vermesine karşın yerli ırkların korunmaya değer görülmesinin başlıca nedeni nedir?', 'Hastalık ve zor koşullara dayanıklılık genlerini taşımaları', ['Daha fazla süt vermeleri', 'Daha büyük boynuzlu olmaları', 'Yalnızca et için uygun olmaları'], 'Yerli ırklar yüzyıllarca yerel iklim, yem ve hastalıklara uyum sağlamıştır; bu genetik çeşitlilik gelecekteki ıslah çalışmaları ve değişen koşullar için değerlidir.'),
  ('Avrupa\'da yaşayan kırmızı geyik ile Kuzey Amerika\'daki wapiti arasındaki ilişki için hangisi doğrudur?', 'Çok yakın akraba türlerdir', ['Biri geyik, diğeri antiloptur', 'Wapiti boynuzsuzdur', 'Kızıl geyik keselidir'], 'Wapiti (elk) ile kızıl geyik çok yakın akrabadır; genetik çalışmalar sonucunda bugün çoğunlukla ayrı türler olarak kabul edilirler.'),
  ('Türkiye\'nin güneydoğusunda bulunan çizgili sırtlan ile Afrika\'daki benekli sırtlanın sosyal yaşamı karşılaştırıldığında hangisi doğrudur?', 'Çizgili sırtlan daha yalnız yaşar', ['İkisi de kalabalık klanlar kurar', 'Çizgili sırtlan dişileri erkeklerden çok daha iridir', 'Benekli sırtlan tamamen otçuldur'], 'Çizgili sırtlan genellikle yalnız ya da küçük gruplar hâlinde leş arar; benekli sırtlan ise dişi baskın, onlarca bireyden oluşan klanlar hâlinde yaşar.'),
  ('Karadeniz ormanlarında yaşayan fındık faresinin (Muscardinus) yaşam biçimi hakkında hangisi doğrudur?', 'Ağaçta yaşar ve kış uykusuna yatar', ['Gündüz etkin bir tarla faresidir', 'Toprak altında yaşayan bir köstebektir', 'Suda yaşayan bir sıçandır'], 'Fındık faresi küçük bir yediuyurgildir; çalılık ve orman kenarlarında ağaçta yaşar, fındık ve meyvelerle beslenir ve kışı uzun bir uykuda geçirir.'),
  ('Güney ve Güneydoğu Asya ormanlarında yaşayan, yaşayan en büyük yabani sığır türü hangisidir?', 'Gaur', ['Yak', 'Banteng', 'Anoa'], 'Gaur (Hint bizonu) omuz yüksekliği iki metreye yaklaşan en iri yabani sığırgildir; ormanlık tepelerde küçük sürüler hâlinde yaşar.'),
  ('Ev farelerinin idrarında bol bulunan ve bireyden bireye farklılık gösteren \'ana idrar proteinleri\' hangi işlevle ilişkilidir?', 'Kokuyla kimlik bildirmek', ['İdrarın donmasını önlemek', 'Yavruları beslemek', 'Kemikleri güçlendirmek'], 'Bu proteinler koku moleküllerini bağlayıp yavaşça salar ve her bireyde biraz farklı bir desen oluşturur; fareler bu sayede birbirlerini kokuyla tanır.'),
  ('Bir deneyde domuzların aynada yansımasını gördükleri yiyeceğin gerçek yerini bulup ona yöneldikleri gözlenmiştir. Bu bulgu en çok neyi gösterir?', 'Yansımadan bilgi çıkarabildiklerini', ['Domuzların hiç görmediğini', 'Domuzların yalnızca kokuyla yön bulduğunu', 'Aynanın domuzları korkuttuğunu'], 'Ayna görüntüsünden yararlanarak gizli bir nesneyi bulmak, yansımanın neyi temsil ettiğini anlamayı gerektiren karmaşık bir bilişsel beceridir.'),
  ('Laboratuvar ölçümlerinde günde yaklaşık 20 saat uyuyarak en uzun uyuyan memelilerden biri olduğu belirlenen hayvan hangisidir?', 'Büyük kahverengi yarasa', ['Zürafa', 'Evcil at', 'Afrika savan fili'], 'Kuzey Amerika\'daki büyük kahverengi yarasa ve küçük kahverengi yarasa günde 19-20 saat uyuyabilir; zürafa, at ve fil ise çok az uyuyan memelilerdir.'),
  ('Afrika dev kese sıçanlarının bazı ülkelerde kara mayınlarını bulmak için eğitilmesinin nedeni nedir?', 'Koku duyuları ve hafiflikleri', ['Toprağı çok hızlı kazmaları', 'Metal dedektörü gibi çalışan bıyıkları', 'Mayınları yiyerek etkisiz hâle getirmeleri'], 'Kese sıçanları güçlü koku duyuları sayesinde patlayıcı maddeleri bulabilir; ağırlıkları mayını tetiklemeye yetmediği için güvenle çalışırlar.'),
  ('Ekidne, pangolin, karıncayiyen, yer domuzu ve numbatın ortak olarak karınca ve termitle beslenmesi ve benzer dil ile burun yapıları taşıması en iyi nasıl açıklanır?', 'Yakınsak evrim', ['Beşinin de aynı takımdan olması', 'Beşinin de Avustralya kökenli olması', 'Beşinin de yumurta bırakması'], 'Bu beş hayvan beş farklı memeli takımına aittir; uzun yapışkan dil, güçlü kazıcı pençeler ve küçülmüş dişler bağımsız olarak, aynı beslenme biçimine uyum sonucu evrimleşmiştir.'),
  ('Memelilerin büyük çoğunluğunun aksine, kendi vücut ısısını sabit tutmakta zorlanan ve sıcaklığı ortama göre geniş aralıkta değişen bir memeli grubu örneği hangisidir?', 'Çıplak köstebek fareleri', ['Kutup ayıları', 'Evcil atlar', 'Ev fareleri'], 'Çıplak köstebek fareleri sabit sıcaklıktaki yer altı tünellerinde yaşar ve vücut ısıları çevreye göre belirgin biçimde değişir; ısınmak için tünelin sıcak kısımlarına geçer ya da birbirine sokulurlar.'),
  ('Dev pandalarda sık rastlanan bir durum olarak, dişi ikiz doğurduğunda doğada genellikle ne olur?', 'Genellikle birine bakar', ['İki yavruyu da kesesinde taşır', 'Yavruları erkek pandaya bırakır', 'İki yavruyu da hemen sütten keser'], 'Dev panda yavruları çok küçük ve bakıma muhtaç doğduğu için anne doğada genellikle tek yavruyu büyütebilir; hayvanat bahçelerinde bakıcılar yavruları dönüşümlü olarak anneye vererek ikisini de yaşatabilir.'),
  ('Dev pandaların birçok ayının aksine kış uykusuna ya da uzun kış dinlenmesine girmemesinin nedeni nedir?', 'Bambunun kışın da bulunması', ['Kalın kürkleri sayesinde hiç üşümemeleri', 'Kışın güneye göç etmeleri', 'Yalnızca yazın uyumaları'], 'Düşük enerjili bambuyla beslenen panda büyük yağ depoları biriktiremez; bambu kışın da bulunduğundan beslenmeyi sürdürür ve soğukta daha alçak yerlere iner.'),
  ('Hudson\'s Bay Company\'nin yaklaşık bir yüzyıllık kürk alım kayıtları, Kanada vaşağı ve kar tavşanı sayılarında hangi ilişkiyi ortaya koymuştur?', 'Yaklaşık on yıllık ortak döngüler', ['İki türün sayısının hiç değişmemesi', 'Vaşak arttıkça tavşanın da hemen artması', 'Tavşanların her yıl tamamen yok olması'], 'Kar tavşanı sayısı yaklaşık 10 yılda bir zirveye ulaşır; ona bağımlı vaşak sayısı da biraz gecikmeyle artıp azalır. Bu kayıtlar avcı-av döngülerinin en ünlü örneklerindendir.'),
  ('Benekli sırtlanların \'gülme\'ye benzetilen yüksek perdeli seslerinin işlevine ilişkin araştırmalar neyi göstermiştir?', 'Sesin sosyal bilgi taşıdığını', ['Sırtlanların gerçekten eğlendiğini', 'Sesin yalnızca avı ürküttüğünü', 'Sesin yağmuru haber verdiğini'], 'Sırtlanların kıkırdama sesleri genellikle gerginlik ve boyun eğme anlarında çıkarılır; sesin perdesi ve tınısı bireyin yaşına ve sıradüzendeki yerine dair ipuçları içerir.'),
  ('Bir araştırmada koyunların düzinelerce farklı koyunun ve bazı insanların yüzünü fotoğraflardan tanıyıp iki yıla yakın hatırlayabildiği gösterilmiştir. Bu bulgu en çok neyi gösterir?', 'Güçlü bir yüz belleklerinin olduğunu', ['Koyunların yalnızca kokuyla tanıdığını', 'Koyunların hiç öğrenemediğini', 'Koyunların renk göremediğini'], 'Bu çalışmalar, koyun beyninde de yüz tanımaya özelleşmiş sinir hücreleri bulunduğunu ve sosyal yaşam için yüz tanımanın önemli olduğunu düşündürür.'),
  ('Bir sıçan yeni bir yiyecek yemiş başka bir sıçanın nefesini kokladıktan sonra aynı yiyeceği daha kolay yemeye başlar. Bu davranış neyin örneğidir?', 'Sosyal öğrenme', ['Kalıtsal tat körlüğü', 'Kış uykusu hazırlığı', 'Bölge savunması'], 'Sıçanlar yuvadaşlarının nefesindeki yiyecek kokusunu, o yiyeceğin güvenli olduğu bilgisiyle ilişkilendirir; bu, zehirli besinlerden kaçınmada yararlı bir sosyal öğrenmedir.'),
];
